volta.css:
:where(:root[data-theme="volta"]) .t-display-xl { font-family: "Bricolage Grotesque", "Arial Black", system-ui, sans-serif; font-size: clamp(56px, 9vw, 112px); line-height: .9; font-weight: 800; letter-spacing: -0.035em; }
:where(:root[data-theme="volta"]) .t-display-l { font-family: "Bricolage Grotesque", "Arial Black", system-ui, sans-serif; font-size: clamp(36px, 5vw, 60px); line-height: .95; font-weight: 800; letter-spacing: -0.03em; }
:where(:root[data-theme="volta"]) .t-display-m { font-family: "Bricolage Grotesque", "Arial Black", system-ui, sans-serif; font-size: 40px; line-height: 40px; font-weight: 700; letter-spacing: -0.02em; }
:where(:root[data-theme="volta"]) .t-title { font-family: "Bricolage Grotesque", "Arial Black", system-ui, sans-serif; font-size: 22px; line-height: 28px; font-weight: 700; letter-spacing: -0.01em; }
:where(:root[data-theme="volta"]) .t-body-l { font-family: "Instrument Sans", system-ui, sans-serif; font-size: 18px; line-height: 28px; font-weight: 400; }
:where(:root[data-theme="volta"]) .t-body { font-family: "Instrument Sans", system-ui, sans-serif; font-size: 15px; line-height: 22px; font-weight: 400; }
:where(:root[data-theme="volta"]) .t-body-s { font-family: "Instrument Sans", system-ui, sans-serif; font-size: 13px; line-height: 18px; font-weight: 400; }
:where(:root[data-theme="volta"]) .t-label { font-family: "Instrument Sans", system-ui, sans-serif; font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }
:where(:root[data-theme="volta"]) .t-numeral { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 40px; line-height: 44px; font-weight: 600; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="volta"]) .t-mono { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="volta"]) { --ds-cover-bg: var(--ds-paper); }
:where(:root[data-theme="volta"]) .v-edge { fill: var(--ds-edge); } :where(:root[data-theme="volta"]) .v-volt { fill: var(--ds-volt); } :where(:root[data-theme="volta"]) .v-acid { fill: var(--ds-acid); } :where(:root[data-theme="volta"]) .v-cobalt { fill: var(--ds-cobalt); } :where(:root[data-theme="volta"]) .v-positive { fill: var(--ds-positive); }
:where(:root[data-theme="volta"]) .v-rim { stroke: var(--ds-edge); stroke-width: 2; } :where(:root[data-theme="volta"]) .v-stripe line { stroke: var(--ds-edge); stroke-width: 4; }
:where(:root[data-theme="volta"]) .v-svg-label { font-family: var(--font-body); font-size: 13px; font-weight: 600; letter-spacing: .08em; fill: var(--ds-ink); } :where(:root[data-theme="volta"]) .v-on-cobalt { fill: var(--ds-on-cobalt); }
:where(:root[data-theme="volta"]) .v-svg-mono { font-family: var(--font-mono); font-size: 12px; letter-spacing: .06em; fill: var(--ds-ink); } :where(:root[data-theme="volta"]) .v-muted-fill { fill: var(--ds-ink-muted); }
:where(:root[data-theme="volta"]) .v-muted { color: var(--ds-ink-muted); } :where(:root[data-theme="volta"]) .v-volt-ink { color: var(--ds-volt-ink); }
:where(:root[data-theme="volta"]) .v-btn { font-family: var(--font-body); font-size: 15px; font-weight: 600; line-height: 20px; padding: 10px 16px; border: 2px solid var(--ds-edge); border-radius: 4px; background: var(--ds-paper-raised); color: var(--ds-ink); box-shadow: var(--ds-shadow-hard); cursor: pointer; transition: transform 80ms ease-out, box-shadow 80ms ease-out; }
:where(:root[data-theme="volta"]) .v-btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 0 var(--ds-edge); }
:where(:root[data-theme="volta"]) .v-btn:active { transform: translate(4px, 4px); box-shadow: 0 0 0 0 var(--ds-edge); }
:where(:root[data-theme="volta"]) .v-btn:focus-visible { outline: none; box-shadow: var(--ds-focus-ring); }
:where(:root[data-theme="volta"]) .v-btn-primary { background: var(--ds-volt); color: var(--ds-on-volt); } :where(:root[data-theme="volta"]) .v-btn-acid { background: var(--ds-acid); color: var(--ds-on-acid); }
:root:where([data-theme="volta"].dark) .v-btn:hover { box-shadow: 6px 6px 0 0 var(--ds-volt); }
:where(:root[data-theme="volta"]) .v-tag { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border-radius: 4px; font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; line-height: 16px; background: var(--ds-paper-sunk); color: var(--ds-ink); }
:where(:root[data-theme="volta"]) .v-tag-acid { background: var(--ds-acid); color: var(--ds-on-acid); } :where(:root[data-theme="volta"]) .v-tag-positive { background: var(--ds-positive-soft); color: var(--ds-positive); } :where(:root[data-theme="volta"]) .v-tag-caution { background: var(--ds-caution-soft); color: var(--ds-caution); } :where(:root[data-theme="volta"]) .v-tag-cobalt { background: var(--ds-cobalt-soft); color: var(--ds-cobalt); }
:where(:root[data-theme="volta"]) .v-stat { display: grid; gap: 6px; padding: 20px 24px; background: var(--ds-paper-raised); border: 2px solid var(--ds-edge); box-shadow: var(--ds-shadow-hard-lg); min-width: 200px; }
:where(:root[data-theme="volta"]) .v-stat-accent { background: var(--ds-volt); color: var(--ds-on-volt); } :where(:root[data-theme="volta"]) .v-stat-accent .t-label, :where(:root[data-theme="volta"]) .v-stat-accent .v-delta { color: var(--ds-on-volt); }
:where(:root[data-theme="volta"]) .v-delta { font-size: 13px; color: var(--ds-ink-muted); } :where(:root[data-theme="volta"]) .v-up { color: var(--ds-positive); } :where(:root[data-theme="volta"]) .v-down { color: var(--ds-negative); }
:where(:root[data-theme="volta"]) .v-callout { padding: 14px 16px; border: 2px solid var(--ds-edge); line-height: 1.5; font-size: 15px; } :where(:root[data-theme="volta"]) .v-callout strong { font-weight: 600; }
:where(:root[data-theme="volta"]) .v-callout-info { background: var(--ds-cobalt-soft); } :where(:root[data-theme="volta"]) .v-callout-positive { background: var(--ds-positive-soft); } :where(:root[data-theme="volta"]) .v-callout-negative { background: var(--ds-negative-soft); }
:where(:root[data-theme="volta"]) .v-hard { border: 2px solid var(--ds-edge); box-shadow: var(--ds-shadow-hard-lg); background: var(--ds-paper-raised); }
:where(:root[data-theme="volta"]) .v-card { padding: 24px; display: grid; gap: 10px; justify-items: start; transition: transform 120ms ease-out; } :where(:root[data-theme="volta"]) .v-card:hover { transform: translate(-2px, -2px); }
:where(:root[data-theme="volta"]) .v-card > * { min-width: 0; max-width: 100%; }
:where(:root[data-theme="volta"]) .v-card h3 { margin: 0; } :where(:root[data-theme="volta"]) .v-card-body { margin: 0; line-height: 1.5; color: var(--ds-ink-muted); max-width: 52ch; } :where(:root[data-theme="volta"]) .v-card .v-btn { margin-top: 8px; }
:where(:root[data-theme="volta"]) .v-panel { padding: 20px; min-width: 0; } :where(:root[data-theme="volta"]) .v-panel .t-label { display: block; margin-bottom: 12px; }
:root:where([data-theme="volta"]) { --ds-hand-ink: var(--ds-edge); --ds-hand-fill: var(--ds-volt); --ds-hand-fill2: var(--ds-cobalt); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-paper-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-shadow: var(--ds-edge); --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 2px solid var(--ds-edge); --ds-tpl-radius: 0; --ds-tpl-tile-shadow: var(--ds-shadow-hard); --ds-tpl-rule: 2px solid var(--ds-edge); --ds-tag-radius: 4px; --ds-slide-title-bg: var(--ds-volt); --ds-slide-title-fg: var(--ds-on-volt); --ds-slide-split-b: var(--ds-cobalt); --ds-slide-split-b-fg: var(--ds-on-cobalt); }
:root:where([data-theme="volta"].dark) { --ds-hand-shadow: var(--ds-volt); }
:where(:root[data-theme="volta"]) .h-num { font-family: var(--font-mono); font-weight: 600; }
:where(:root[data-theme="volta"]) .ds-tpl-tag.is-idle { background: var(--ds-paper-sunk); }
:where(:root[data-theme="volta"]) .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-width: 2px; }
:where(:root[data-theme="volta"]) .ds-tpl-split-a { color: var(--ds-on-volt); }
