:where(:root[data-theme="phosphor"]) .ds-tpl-row .ds-tpl-tag { grid-column: 2; grid-row: 1 / span 2; }
:where(:root[data-theme="phosphor"]) .ds-tpl-tag { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: var(--ds-tag-radius, 999px); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; line-height: 16px; background: var(--muted); color: var(--foreground); }
:where(:root[data-theme="phosphor"]) .ds-tpl-tag.is-idle { background: var(--muted); color: var(--muted-foreground); }
:where(:root[data-theme="phosphor"]) .ds-tpl-tag.is-ok { background: var(--ds-positive-soft); color: var(--ds-positive); } :where(:root[data-theme="phosphor"]) .ds-tpl-tag.is-warn { background: var(--ds-caution-soft); color: var(--ds-caution); } :where(:root[data-theme="phosphor"]) .ds-tpl-tag.is-bad { background: var(--ds-negative-soft); color: var(--ds-negative); }
:where(:root[data-theme="phosphor"]) .ds-tpl-form { display: grid; gap: 14px; align-items: end; margin-top: 16px; padding-top: 16px; border-top: var(--ds-tpl-rule, 1px solid var(--border)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-landing { padding: 0; }
:where(:root[data-theme="phosphor"]) .ds-tpl-hero { display: grid; gap: 20px; padding: 32px 24px; background: var(--ds-hero-bg, var(--background)); color: var(--ds-hero-fg, var(--foreground)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-hero .ds-row { color: var(--foreground); }
:where(:root[data-theme="phosphor"]) .ds-tpl-hero-h { margin: 0; font-size: clamp(36px, 5.2vw, 64px); max-width: 14ch; }
:where(:root[data-theme="phosphor"]) .ds-tpl-hero-sub { margin: 16px 0 24px; font-size: 18px; line-height: 1.5; max-width: 44ch; color: var(--ds-hero-muted, var(--muted-foreground)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-hero-art svg { display: block; width: 100%; height: auto; }
:where(:root[data-theme="phosphor"]) .ds-tpl-feats { display: grid; gap: 0; border-top: var(--ds-tpl-rule, 1px solid var(--border)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-feat { padding: 20px 24px; border-bottom: 1px solid var(--border); } :where(:root[data-theme="phosphor"]) .ds-tpl-feat h4 { margin: 0; } :where(:root[data-theme="phosphor"]) .ds-tpl-feat p { margin: 8px 0 0; font-size: 14px; line-height: 1.5; color: var(--muted-foreground); }
:where(:root[data-theme="phosphor"]) .ds-tpl-plan { padding: 24px; }
:where(:root[data-theme="phosphor"]) .ds-tpl-plan-h { margin: 6px 0 0; }
:where(:root[data-theme="phosphor"]) .ds-tpl-plan-brief { display: grid; gap: 14px; margin-top: 18px; padding-top: 16px; border-top: var(--ds-tpl-rule, 1px solid var(--border)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-plan-brief .t-label { color: var(--muted-foreground); } :where(:root[data-theme="phosphor"]) .ds-tpl-plan-brief p { margin: 6px 0 0; font-size: 14px; line-height: 1.5; }
:where(:root[data-theme="phosphor"]) .ds-tpl-plan-sub { margin: 28px 0 12px; color: var(--primary); }
:where(:root[data-theme="phosphor"]) .ds-tpl-wires { display: grid; gap: 12px; }
:where(:root[data-theme="phosphor"]) .ds-tpl-wire { background: var(--ds-hand-bg, var(--muted)); border: var(--ds-tpl-edge, 1px solid var(--border)); border-radius: var(--ds-tpl-radius, var(--radius)); padding: 12px; min-width: 0; }
:where(:root[data-theme="phosphor"]) .ds-tpl-wire svg { display: block; width: 100%; height: auto; }
:where(:root[data-theme="phosphor"]) .ds-tpl-wire-cap { margin: 10px 0 0; font-size: 13px; line-height: 1.5; color: var(--muted-foreground); max-width: 70ch; }
:where(:root[data-theme="phosphor"]) .ds-tpl-flow { border: var(--ds-tpl-edge, 1px solid var(--border)); border-radius: var(--ds-tpl-radius, var(--radius)); padding: 12px; background: var(--card); overflow-x: auto; }
:where(:root[data-theme="phosphor"]) .ds-tpl-decisions { display: grid; gap: 12px; }
:where(:root[data-theme="phosphor"]) .ds-tpl-decision { padding: 14px 16px; border-left: 3px solid var(--primary); background: var(--card); border-radius: 0 var(--ds-tpl-radius, var(--radius)) var(--ds-tpl-radius, var(--radius)) 0; }
:where(:root[data-theme="phosphor"]) .ds-tpl-decision h4 { margin: 0; } :where(:root[data-theme="phosphor"]) .ds-tpl-decision p { margin: 6px 0 0; font-size: 14px; line-height: 1.5; color: var(--muted-foreground); }
:where(:root[data-theme="phosphor"]) .ds-tpl-ledger { width: 100%; border-collapse: collapse; font-size: 14px; border: 0; }
:where(:root[data-theme="phosphor"]) .ds-tpl-ledger th, :where(:root[data-theme="phosphor"]) .ds-tpl-ledger td { border-left: 0; border-right: 0; border-top: 0; background: transparent; text-align: left; padding: 10px 12px 10px 0; border-bottom: 1px solid var(--border); vertical-align: middle; }
:where(:root[data-theme="phosphor"]) .ds-tpl-ledger th { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--muted-foreground); font-weight: 600; border-bottom: var(--ds-tpl-rule, 1px solid var(--foreground)); }
:where(:root[data-theme="phosphor"]) .ds-tpl-ledger s { color: var(--muted-foreground); }
@container (min-width: 760px) {
  :where(:root[data-theme="phosphor"]) .ds-tpl-wires { grid-template-columns: 3fr 2fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-plan-brief { grid-template-columns: 1fr 1fr 1fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-decisions { grid-template-columns: 1fr 1fr 1fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-head { flex-wrap: nowrap; } :where(:root[data-theme="phosphor"]) .ds-tpl-head h3 { flex: 0 0 160px; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-kpis { grid-template-columns: 1fr 1fr 1fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-dash-grid { grid-template-columns: 3fr 2fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-slides { grid-template-columns: 1fr 1fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-ed-cols { grid-template-columns: minmax(0, 1fr) 220px; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-scrolly { grid-template-columns: 1fr 1fr; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-form { grid-template-columns: 1fr 1fr auto; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-hero { grid-template-columns: 3fr 2fr; align-items: center; padding: 48px 40px; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-feats { grid-template-columns: 1fr 1fr 1fr; } :where(:root[data-theme="phosphor"]) .ds-tpl-feat { border-bottom: 0; border-right: 1px solid var(--border); } :where(:root[data-theme="phosphor"]) .ds-tpl-feat:last-child { border-right: 0; }
  :where(:root[data-theme="phosphor"]) .ds-tpl-row { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) auto; } :where(:root[data-theme="phosphor"]) .ds-tpl-row-meta { grid-column: auto; } :where(:root[data-theme="phosphor"]) .ds-tpl-row .ds-tpl-tag { grid-column: auto; grid-row: auto; }
}

