:where(:root[data-theme="drafting"]) .t-display-xl { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: clamp(48px, 8vw, 104px); line-height: .9; font-weight: 900; letter-spacing: -0.03em; text-transform: uppercase; }
:where(:root[data-theme="drafting"]) .t-display-l { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: clamp(32px, 4.5vw, 56px); line-height: .95; font-weight: 900; letter-spacing: -0.025em; text-transform: uppercase; }
:where(:root[data-theme="drafting"]) .t-title { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: 22px; line-height: 26px; font-weight: 700; letter-spacing: -0.01em; }
:where(:root[data-theme="drafting"]) .t-body { font-family: "Archivo", system-ui, sans-serif; font-size: 16px; line-height: 26px; font-weight: 400; }
