meridian.css:
:where(:root[data-theme="meridian"]) .t-display-xl { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: clamp(48px, 7vw, 96px); line-height: .98; font-weight: 600; letter-spacing: -0.045em; }
:where(:root[data-theme="meridian"]) .t-display-l { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: clamp(32px, 4.2vw, 52px); line-height: 1.04; font-weight: 600; letter-spacing: -0.04em; }
:where(:root[data-theme="meridian"]) .t-display-m { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 28px; line-height: 32px; font-weight: 600; letter-spacing: -0.03em; }
:where(:root[data-theme="meridian"]) .t-title { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 16px; line-height: 22px; font-weight: 600; letter-spacing: -0.015em; }
:where(:root[data-theme="meridian"]) .t-body-l { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 18px; line-height: 28px; font-weight: 400; letter-spacing: -0.01em; }
:where(:root[data-theme="meridian"]) .t-body { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 14px; line-height: 22px; font-weight: 400; }
:where(:root[data-theme="meridian"]) .t-body-s { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 13px; line-height: 18px; font-weight: 400; }
:where(:root[data-theme="meridian"]) .t-label { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: 0.01em; }
:where(:root[data-theme="meridian"]) .t-eyebrow { font-family: "Geist Mono", ui-monospace, Menlo, monospace; font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: 0.02em; }
:where(:root[data-theme="meridian"]) .t-numeral { font-family: "Geist", "Inter", system-ui, sans-serif; font-size: 36px; line-height: 40px; font-weight: 600; letter-spacing: -0.035em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="meridian"]) .t-mono { font-family: "Geist Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="meridian"]) { --ds-cover-bg: var(--ds-canvas); --ds-hand-ink: var(--ds-ink-faint); --ds-hand-fill: var(--ds-blue); --ds-hand-fill2: var(--ds-blue); --ds-hand-muted: var(--ds-surface-sunk); --ds-hand-ground: var(--ds-surface); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-bg: var(--ds-canvas); --ds-hand-text-stroke: var(--ds-surface);
  --ds-tpl-edge: 1px solid var(--ds-hairline); --ds-tpl-radius: 8px; --ds-tpl-rule: 1px solid var(--ds-hairline); --ds-tpl-tile-shadow: var(--ds-shadow-tile); --ds-tag-radius: 999px; --ds-slide-bg: var(--ds-surface); --ds-slide-title-bg: var(--ds-ink); --ds-slide-title-fg: var(--ds-canvas); --ds-slide-split-a: var(--ds-blue); --ds-slide-split-b: var(--ds-surface-sunk); --ds-slide-split-b-fg: var(--ds-ink); --ds-slide-h-size: 9cqw;
  --ds-hero-bg: var(--ds-glow), var(--ds-surface); }
:where(:root[data-theme="meridian"]) .ds-tpl-kicker, :where(:root[data-theme="meridian"]) .ds-tpl-plan-sub { font-family: var(--font-mono); font-size: 12px; } :where(:root[data-theme="meridian"]) .ds-tpl-kicker::before, :where(:root[data-theme="meridian"]) .ds-tpl-plan-sub::before { content: "● "; font-size: 9px; vertical-align: 1px; }
:where(:root[data-theme="meridian"]) .ds-tpl-stage-top, :where(:root[data-theme="meridian"]) .ds-tpl-stage-foot { text-transform: none; letter-spacing: .02em; }
:where(:root[data-theme="meridian"]) .ds-tpl-tag { text-transform: none; letter-spacing: 0; font-weight: 500; padding-left: 8px; } :where(:root[data-theme="meridian"]) .ds-tpl-tag::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
:where(:root[data-theme="meridian"]) .ds-tpl-ledger th { text-transform: none; letter-spacing: 0; font-weight: 500; background: var(--ds-surface-sunk); padding-left: 10px; border-bottom: 1px solid var(--ds-hairline-strong); } :where(:root[data-theme="meridian"]) .ds-tpl-ledger td { padding-left: 10px; }
:where(:root[data-theme="meridian"]) .ds-tpl-decision { border-left-width: 2px; box-shadow: var(--ds-shadow-tile); border-top: 1px solid var(--ds-hairline); border-right: 1px solid var(--ds-hairline); border-bottom: 1px solid var(--ds-hairline); }
:where(:root[data-theme="meridian"]) .ds-tpl-pull { border-top-width: 1px; border-top-color: var(--ds-hairline-strong); }
:where(:root[data-theme="meridian"]) .ds-tpl-dropcap { color: var(--ds-ink); }
:where(:root[data-theme="meridian"]) .ds-tpl-split-b { border: 1px solid var(--ds-hairline); }
:where(:root[data-theme="meridian"]) .h-num { font-family: var(--font-sans); font-weight: 600; letter-spacing: -.03em; fill: var(--ds-ink); }
:where(:root[data-theme="meridian"]) .h-text { fill: var(--ds-ink-soft); }
:where(:root[data-theme="meridian"]) .h-fill.h-outline-fill { fill: var(--ds-blue-soft); stroke: var(--ds-blue); stroke-width: 1.5; }
:where(:root[data-theme="meridian"]) .h-fill2.h-outline-fill { fill: none; stroke: var(--ds-blue); stroke-width: 1.5; opacity: .45; }
:where(:root[data-theme="meridian"]) .me-ground { fill: var(--ds-canvas); } :where(:root[data-theme="meridian"]) .me-glow-a { stop-color: var(--ds-blue); stop-opacity: var(--ds-glow-a); } :where(:root[data-theme="meridian"]) .me-glow-b { stop-color: var(--ds-blue); stop-opacity: 0; }
:where(:root[data-theme="meridian"]) .me-frame { fill: var(--ds-surface); stroke: var(--ds-hairline-strong); stroke-width: 1; }
:where(:root[data-theme="meridian"]) .me-card, :where(:root[data-theme="meridian"]) .me-surface { fill: var(--ds-surface); stroke: var(--ds-hairline); stroke-width: 1; } :where(:root[data-theme="meridian"]) .me-surface { stroke: none; }
:where(:root[data-theme="meridian"]) .me-palette { fill: var(--ds-surface); stroke: var(--ds-hairline-strong); stroke-width: 1; } :where(:root[data-theme="meridian"]) .me-shadow { fill: var(--ds-ink); opacity: .08; } :root:where([data-theme="meridian"].dark) .me-shadow { opacity: .5; }
:where(:root[data-theme="meridian"]) .me-dot { fill: var(--ds-hairline-strong); } :where(:root[data-theme="meridian"]) .me-line-h { fill: var(--ds-surface-sunk); } :where(:root[data-theme="meridian"]) .me-line-on { fill: var(--ds-hairline-strong); } :where(:root[data-theme="meridian"]) .me-hair { stroke: var(--ds-hairline); stroke-width: 1; } :where(:root[data-theme="meridian"]) .me-hair-dash { stroke: var(--ds-hairline); stroke-width: 1; stroke-dasharray: 2 4; }
:where(:root[data-theme="meridian"]) .me-active { fill: var(--ds-blue-soft); } :where(:root[data-theme="meridian"]) .me-avatar-sq { fill: var(--ds-ink); } :where(:root[data-theme="meridian"]) .me-caret { stroke: var(--ds-blue); stroke-width: 1.5; }
:where(:root[data-theme="meridian"]) .me-pill-k { fill: var(--ds-surface-sunk); stroke: var(--ds-hairline); stroke-width: 1; } :where(:root[data-theme="meridian"]) .me-pill-kt { font-family: var(--font-mono); font-size: 8px; fill: var(--ds-ink-soft); }
:where(:root[data-theme="meridian"]) .me-blue { fill: var(--ds-hand-fill); } :where(:root[data-theme="meridian"]) .me-blue-stroke { fill: none; stroke: var(--ds-hand-fill); stroke-width: 2; stroke-linecap: round; }
:where(:root[data-theme="meridian"]) .me-bar { fill: var(--ds-hairline-strong); } :where(:root[data-theme="meridian"]) .me-track { fill: var(--ds-surface-sunk); } :where(:root[data-theme="meridian"]) .me-warn { fill: var(--ds-caution); }
:where(:root[data-theme="meridian"]) .me-key { fill: var(--ds-surface); stroke: var(--ds-hairline-strong); stroke-width: 1; } :where(:root[data-theme="meridian"]) .me-key-t { font-family: var(--font-mono); font-size: 10px; font-weight: 500; fill: var(--ds-ink); } :where(:root[data-theme="meridian"]) .me-key-big { font-size: 22px; }
