:where(:root[data-theme="meridian"]) .ds-tpl-ledger th, :where(:root[data-theme="meridian"]) .ds-tpl-ledger td { border-left: 0; border-right: 0; border-top: 0; background: transparent; text-align: left; padding: 10px 12px 10px 0; border-bottom: 1px solid var(--border); vertical-align: middle; }
:where(:root[data-theme="meridian"]) .ds-tpl-ledger th { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--muted-foreground); font-weight: 600; border-bottom: var(--ds-tpl-rule, 1px solid var(--foreground)); }
:where(:root[data-theme="meridian"]) .ds-tpl-ledger s { color: var(--muted-foreground); }
@container (min-width: 760px) {
  :where(:root[data-theme="meridian"]) .ds-tpl-wires { grid-template-columns: 3fr 2fr; }
  :where(:root[data-theme="meridian"]) .ds-tpl-plan-brief { grid-template-columns: 1fr 1fr 1fr; }
  :where(:root[data-theme="meridian"]) .ds-tpl-decisions { grid-template-columns: 1fr 1fr 1fr; }
  :where(:root[data-theme="meridian"]) .ds-tpl-head { flex-wrap: nowrap; } :where(:root[data-theme="meridian"]) .ds-tpl-head h3 { flex: 0 0 160px; }
