dossier.css:
:where(:root[data-theme="dossier"]) .t-display-xl { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: clamp(64px, 12vw, 160px); line-height: .8; font-weight: 900; letter-spacing: -0.01em; text-transform: uppercase; font-stretch: 62%; }
:where(:root[data-theme="dossier"]) .t-display-l { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: clamp(40px, 6.5vw, 88px); line-height: .84; font-weight: 900; letter-spacing: -0.01em; text-transform: uppercase; font-stretch: 62%; }
:where(:root[data-theme="dossier"]) .t-display-m { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: 36px; line-height: 36px; font-weight: 800; letter-spacing: -0.005em; text-transform: uppercase; font-stretch: 75%; }
:where(:root[data-theme="dossier"]) .t-title { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: 20px; line-height: 24px; font-weight: 800; letter-spacing: 0.005em; text-transform: uppercase; font-stretch: 80%; }
:where(:root[data-theme="dossier"]) .t-body-l { font-family: "Newsreader", Georgia, serif; font-size: 21px; line-height: 1.4; font-weight: 400; }
:where(:root[data-theme="dossier"]) .t-body { font-family: "Newsreader", Georgia, serif; font-size: 18px; line-height: 1.56; font-weight: 400; }
:where(:root[data-theme="dossier"]) .t-body-ui { font-family: "Archivo", system-ui, sans-serif; font-size: 15px; line-height: 22px; font-weight: 400; }
:where(:root[data-theme="dossier"]) .t-body-s { font-family: "Archivo", system-ui, sans-serif; font-size: 13px; line-height: 18px; font-weight: 400; }
:where(:root[data-theme="dossier"]) .t-label { font-family: "IBM Plex Mono", ui-monospace, Menlo, monospace; font-size: 11px; line-height: 16px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }
:where(:root[data-theme="dossier"]) .t-numeral { font-family: "Archivo", "Arial Narrow", system-ui, sans-serif; font-size: 48px; line-height: 48px; font-weight: 800; letter-spacing: -0.01em; font-stretch: 75%; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="dossier"]) .t-mono { font-family: "IBM Plex Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="dossier"]) { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-violet); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-paper-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-tex: 2; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 1.5px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 3px solid var(--ds-ink); --ds-tag-radius: 2px; --ds-slide-bg: var(--ds-paper-raised); --ds-slide-title-bg: var(--ds-night); --ds-slide-title-fg: var(--ds-on-night); --ds-slide-split-a: var(--ds-violet); --ds-slide-split-a-fg: var(--ds-on-violet); --ds-slide-split-b: var(--ds-ink); --ds-slide-split-b-fg: var(--ds-paper); }
:where(:root[data-theme="dossier"]) .ds-tpl-brand, :where(:root[data-theme="dossier"]) .ds-tpl-slide-h, :where(:root[data-theme="dossier"]) .ds-tpl-hero-h, :where(:root[data-theme="dossier"]) .ds-tpl-ed-h, :where(:root[data-theme="dossier"]) .ds-tpl-dropcap { text-transform: uppercase; font-stretch: 62%; font-weight: 900; }
:where(:root[data-theme="dossier"]) .ds-tpl-slide-big, :where(:root[data-theme="dossier"]) .ds-tpl-pull-n, :where(:root[data-theme="dossier"]) .h-num { font-stretch: 75%; font-weight: 800; }
:where(:root[data-theme="dossier"]) .ds-tpl-tag { font-family: var(--font-mono); border: 1.5px solid currentColor; }
:where(:root[data-theme="dossier"]) .ds-tpl-tag.is-idle { border-style: dashed; background: transparent; }
:where(:root[data-theme="dossier"]) .ds-tpl-stage-top, :where(:root[data-theme="dossier"]) .ds-tpl-stage-foot { font-weight: 700; }
:where(:root[data-theme="dossier"]) .ds-tpl-ed-body { font-family: var(--font-body); }
:where(:root[data-theme="dossier"]) .ds-tpl-row-name { font-family: var(--font-display); font-stretch: 80%; text-transform: uppercase; }
/* svg vocabulary */
:where(:root[data-theme="dossier"]) .do-paper { fill: var(--ds-paper); } :where(:root[data-theme="dossier"]) .do-ink, :where(:root[data-theme="dossier"]) .do-fillink { fill: var(--ds-hand-ink); } :where(:root[data-theme="dossier"]) .do-night { fill: var(--ds-night); } :where(:root[data-theme="dossier"]) .do-lime { fill: var(--ds-lime); }
:where(:root[data-theme="dossier"]) .do-hatch line { stroke: var(--ds-hand-fill); stroke-width: 2; } :where(:root[data-theme="dossier"]) .do-violet-rim { fill: none; stroke: var(--ds-hand-ink); stroke-width: 2; }
:where(:root[data-theme="dossier"]) .do-stamp-rim { fill: none; stroke: var(--ds-hand-fill); stroke-width: 3; } :where(:root[data-theme="dossier"]) .do-stamp-rim-thin { fill: none; stroke: var(--ds-hand-fill); stroke-width: 1.5; }
:where(:root[data-theme="dossier"]) .do-svg-mono { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .14em; fill: var(--ds-hand-ink); } :where(:root[data-theme="dossier"]) .do-svg-soft { fill: var(--ds-ink-soft); } :where(:root[data-theme="dossier"]) .do-on-night { fill: var(--ds-on-night); } :where(:root[data-theme="dossier"]) .do-on-hatch { fill: var(--ds-hand-ink); }
:where(:root[data-theme="dossier"]) .do-svg-numblock { font-family: var(--font-mono); font-size: 22px; font-weight: 700; fill: var(--ds-paper); } :where(:root[data-theme="dossier"]) .do-on-ink { fill: var(--ds-paper); }
:where(:root[data-theme="dossier"]) .do-svg-head { font-family: var(--font-display); font-weight: 900; font-stretch: 62%; font-size: 56px; letter-spacing: -.01em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="dossier"]) .do-svg-head-l { font-family: var(--font-display); font-weight: 900; font-stretch: 62%; font-size: 48px; letter-spacing: -.01em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="dossier"]) .do-svg-stamp { font-family: var(--font-mono); font-size: 16px; font-weight: 700; letter-spacing: .16em; fill: var(--ds-hand-fill); }
:where(:root[data-theme="dossier"]) .do-svg-tag { fill: none; stroke: var(--ds-hand-ink); stroke-width: 1.5; } :where(:root[data-theme="dossier"]) .do-svg-tag-intel { stroke-dasharray: 4 3; }
:where(:root[data-theme="dossier"]) .do-svg-tagtext { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .14em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="dossier"]) .do-svg-body { font-family: var(--font-body); font-size: 17px; fill: var(--ds-hand-ink); }
/* authored components */
:where(:root[data-theme="dossier"]) .do-btn { font-family: var(--font-mono); font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; line-height: 16px; padding: 11px 16px; border: 1.5px solid var(--ds-ink); border-radius: 2px; background: transparent; color: var(--ds-ink); cursor: pointer; transition: background 120ms linear, color 120ms linear; }
:where(:root[data-theme="dossier"]) .do-btn:hover { background: var(--ds-ink); color: var(--ds-paper); }
:where(:root[data-theme="dossier"]) .do-btn:focus-visible { outline: 3px solid var(--ds-violet); outline-offset: 2px; }
:where(:root[data-theme="dossier"]) .do-btn-primary { background: var(--ds-violet); border-color: var(--ds-violet); color: var(--ds-on-violet); } :where(:root[data-theme="dossier"]) .do-btn-primary:hover { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-paper); }
:where(:root[data-theme="dossier"]) .do-btn-lime { background: var(--ds-lime); border-color: var(--ds-ink); color: var(--ds-on-lime); }
:where(:root[data-theme="dossier"]) .do-tag { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; line-height: 1.2; padding: 3px 7px; border: 1.5px solid currentColor; border-radius: 2px; white-space: nowrap; color: var(--ds-ink); }
:where(:root[data-theme="dossier"]) .do-tag-intel { border-style: dashed; } :where(:root[data-theme="dossier"]) .do-tag-plan { background: var(--ds-ink); color: var(--ds-paper); } :where(:root[data-theme="dossier"]) .do-tag-verified { border-width: 3px; border-style: double; }
:where(:root[data-theme="dossier"]) .do-tag-lime { background: var(--ds-lime); color: var(--ds-on-lime); border-color: var(--ds-ink); }
:where(:root[data-theme="dossier"]) .do-tag-status.is-ok { background: var(--ds-positive-soft); color: var(--ds-positive); } :where(:root[data-theme="dossier"]) .do-tag-status.is-warn { background: var(--ds-caution-soft); color: var(--ds-caution); } :where(:root[data-theme="dossier"]) .do-tag-status.is-bad { background: var(--ds-negative-soft); color: var(--ds-negative); }
:where(:root[data-theme="dossier"]) .do-hl { font-style: normal; position: relative; display: inline-block; isolation: isolate; }
:where(:root[data-theme="dossier"]) .do-hl::after { content: ""; position: absolute; left: -.04em; right: -.04em; bottom: .04em; height: .22em; background: var(--ds-lime); z-index: -1; transform: skewX(-8deg); }
:where(:root[data-theme="dossier"]) .do-redact { display: inline-block; background: currentColor; height: .95em; vertical-align: -.12em; border-radius: 1px; }
:where(:root[data-theme="dossier"]) .do-stamp { display: inline-block; font-family: var(--font-mono); font-weight: 700; font-size: 13px; letter-spacing: .16em; text-transform: uppercase; color: var(--ds-violet); border: 3px solid currentColor; border-radius: 3px; padding: 6px 10px; line-height: 1.15; transform: rotate(-6deg); outline: 1.5px solid currentColor; outline-offset: 3px; }
:where(:root[data-theme="dossier"]) .do-fact { display: grid; gap: 4px; padding: 14px 16px 14px 0; border-top: 3px solid var(--ds-ink); min-width: 150px; } :where(:root[data-theme="dossier"]) .do-fact-accent .t-numeral { color: var(--ds-violet); }
:where(:root[data-theme="dossier"]) .do-callout { display: grid; gap: 8px; justify-items: start; padding: 14px 16px; border: 1.5px solid var(--ds-ink); font-family: var(--font-body); font-size: 17px; line-height: 1.45; } :where(:root[data-theme="dossier"]) .do-callout p { margin: 0; }
:where(:root[data-theme="dossier"]) .do-callout-intel { background: var(--ds-caution-soft); } :where(:root[data-theme="dossier"]) .do-callout-ok { background: var(--ds-positive-soft); } :where(:root[data-theme="dossier"]) .do-callout-bad { background: var(--ds-negative-soft); }
:where(:root[data-theme="dossier"]) .do-file { position: relative; background: var(--ds-paper-raised); color: var(--ds-ink); padding: 22px 22px 20px; border: 1.5px solid var(--ds-ink); box-shadow: var(--ds-shadow-file); margin: 26px 0 30px; max-width: 420px; }
:where(:root[data-theme="dossier"]) .do-file-tab { position: absolute; top: -26px; left: -1.5px; background: var(--ds-ink); color: var(--ds-paper); font-family: var(--font-mono); font-weight: 700; font-size: 11px; letter-spacing: .2em; text-transform: uppercase; padding: 6px 14px 5px; clip-path: polygon(0 0, 86% 0, 100% 100%, 0 100%); }
:where(:root[data-theme="dossier"]) .do-file-dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 0 14px; }
:where(:root[data-theme="dossier"]) .do-file-dl dt, :where(:root[data-theme="dossier"]) .do-file-dl dd { margin: 0; padding: 8px 0; border-bottom: 1px solid var(--ds-line); font-size: 14px; }
:where(:root[data-theme="dossier"]) .do-file-dl dt { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--ds-ink-soft); padding-top: 10px; }
:where(:root[data-theme="dossier"]) .do-file-dl dd { font-weight: 600; font-family: var(--font-display); font-stretch: 90%; }
:where(:root[data-theme="dossier"]) .do-file .do-stamp { position: absolute; right: 14px; bottom: -22px; background: var(--ds-paper-raised); }
/* sample */
:where(:root[data-theme="dossier"]) .do-mast { display: flex; justify-content: space-between; gap: 16px; padding: 14px 20px 10px; border-bottom: 3px solid var(--ds-ink); font-family: var(--font-mono); font-size: 11px; font-weight: 500; letter-spacing: .14em; text-transform: uppercase; } :where(:root[data-theme="dossier"]) .do-mast b { font-weight: 700; } :where(:root[data-theme="dossier"]) .do-mast-mid { display: none; }
:where(:root[data-theme="dossier"]) .do-kicker { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 32px 0 0; font-family: var(--font-mono); font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; }
:where(:root[data-theme="dossier"]) .do-h1 { margin: 12px 0 0; } :where(:root[data-theme="dossier"]) .do-l1, :where(:root[data-theme="dossier"]) .do-l2 { display: block; } :where(:root[data-theme="dossier"]) .do-l2 { color: var(--ds-violet); }
