riso.css:
:where(:root[data-theme="riso"]) .t-display-xl { font-family: "Fraunces", Georgia, serif; font-size: clamp(64px, 12vw, 160px); line-height: .82; font-weight: 900; letter-spacing: -0.045em; }
:where(:root[data-theme="riso"]) .t-display-l { font-family: "Fraunces", Georgia, serif; font-size: clamp(40px, 6.4vw, 84px); line-height: .9; font-weight: 900; letter-spacing: -0.03em; }
