:where(:root[data-theme="riso"]) .t-title { font-family: "Fraunces", Georgia, serif; font-size: 24px; line-height: 28px; font-weight: 900; letter-spacing: -0.01em; }
:where(:root[data-theme="riso"]) .t-deck { font-family: "Fraunces", Georgia, serif; font-size: clamp(20px, 2vw, 26px); line-height: 1.25; font-weight: 500; font-style: italic; }
:where(:root[data-theme="riso"]) .t-body-l { font-family: "Fraunces", Georgia, serif; font-size: 20px; line-height: 1.5; font-weight: 500; }
