:where(:root[data-theme="riso"]) .t-body-s { font-family: "Fraunces", Georgia, serif; font-size: 14px; line-height: 1.45; font-weight: 500; }
:where(:root[data-theme="riso"]) .t-label { font-family: "Space Mono", ui-monospace, Menlo, monospace; font-size: 12px; line-height: 16px; font-weight: 400; letter-spacing: 0.09em; text-transform: uppercase; }
:where(:root[data-theme="riso"]) .t-numeral { font-family: "Space Mono", ui-monospace, Menlo, monospace; font-size: 40px; line-height: 44px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="riso"]) .t-mono { font-family: "Space Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="riso"]) { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-key); --ds-hand-fill: var(--ds-blue); --ds-hand-fill2: var(--ds-pink); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-sheet); --ds-hand-stroke: 2; --ds-hand-cap: round; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 2px solid var(--ds-key); --ds-tpl-radius: 0; --ds-tpl-rule: 1.5px dashed var(--ds-key); --ds-tpl-tile-shadow: var(--ds-shadow-hard); --ds-tag-radius: 0;
  --ds-slide-bg: var(--ds-sheet); --ds-slide-fg: var(--ds-key); --ds-slide-title-bg: var(--ds-blue); --ds-slide-title-fg: var(--ds-on-blue); --ds-slide-split-a: var(--ds-blue); --ds-slide-split-a-fg: var(--ds-on-blue); --ds-slide-split-b: var(--ds-pink); --ds-slide-split-b-fg: var(--ds-on-pink); --ds-hero-bg: var(--ds-paper); }
:where(:root[data-theme="riso"]) .ri-paper { fill: var(--ds-paper); } :where(:root[data-theme="riso"]) .ri-sheet { fill: var(--ds-sheet); } :where(:root[data-theme="riso"]) .ri-manila { fill: var(--ds-manila); } :where(:root[data-theme="riso"]) .ri-proof { fill: var(--ds-sheet); stroke: var(--ds-line); stroke-width: 1.5; }
:where(:root[data-theme="riso"]) .ri-blue { fill: var(--ds-hand-fill, var(--ds-blue)); } :where(:root[data-theme="riso"]) .ri-pink { fill: var(--ds-hand-fill2, var(--ds-pink)); } :where(:root[data-theme="riso"]) .ri-yellow { fill: var(--ds-yellow); } :where(:root[data-theme="riso"]) .ri-key { fill: var(--ds-hand-ink, var(--ds-key)); }
:where(:root[data-theme="riso"]) .ri-mult { mix-blend-mode: multiply; } :root:where([data-theme="riso"].dark) .ri-mult { mix-blend-mode: normal; opacity: .9; }
:root:where([data-theme="riso"].dark) .h-plate { mix-blend-mode: normal; opacity: .9; }
:where(:root[data-theme="riso"]) .ri-key-line { fill: none; stroke: var(--ds-hand-ink, var(--ds-key)); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
:where(:root[data-theme="riso"]) .ri-dots-pink circle { fill: var(--ds-hand-fill2, var(--ds-pink)); mix-blend-mode: multiply; }
:where(:root[data-theme="riso"]) .ri-mono { font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; fill: var(--ds-hand-ink, var(--ds-key)); } :where(:root[data-theme="riso"]) .ri-on-key { fill: var(--ds-sheet); } :where(:root[data-theme="riso"]) .ri-on-manila { fill: var(--ds-on-yellow); } :where(:root[data-theme="riso"]) .ri-navy { fill: var(--ds-on-yellow); } :where(:root[data-theme="riso"]) .ri-on-navy { fill: #F3ECDC; }
:where(:root[data-theme="riso"]) .ri-ovp-t { font-family: var(--font-display); font-size: 120px; font-weight: 900; letter-spacing: -.04em; font-variation-settings: "SOFT" 100, "WONK" 1; }
:where(:root[data-theme="riso"]) .ri-tag-h { font-family: var(--font-display); font-size: 34px; font-weight: 900; letter-spacing: -.02em; fill: var(--ds-key); font-variation-settings: "SOFT" 100, "WONK" 1; }
:where(:root[data-theme="riso"]) .ri-hole { fill: var(--ds-paper); stroke: var(--ds-key); stroke-width: 4; } :where(:root[data-theme="riso"]) .ri-string { fill: none; stroke: var(--ds-key); stroke-width: 2; stroke-dasharray: 4 4; }
:where(:root[data-theme="riso"]) .ri-tag-h { fill: var(--ds-on-yellow); } :where(:root[data-theme="riso"]) .ri-hole { fill: var(--ds-paper); stroke: var(--ds-on-yellow); } :root:where([data-theme="riso"].dark) .ri-tag-string, :where(:root[data-theme="riso"]) .ri-string { stroke: var(--ds-key); }
:where(:root[data-theme="riso"]) .ri-btn { font-family: var(--font-mono); font-size: 13px; letter-spacing: .06em; text-transform: uppercase; line-height: 20px; padding: 10px 16px; border: 2px solid var(--ds-key); background: var(--ds-sheet); color: var(--ds-key); box-shadow: var(--ds-shadow-hard); cursor: pointer; transition: transform 80ms ease-out, box-shadow 80ms ease-out; }
:where(:root[data-theme="riso"]) .ri-btn:hover { transform: translate(-2px, -2px); box-shadow: 8px 8px 0 0 var(--ds-key); } :root:where([data-theme="riso"].dark) .ri-btn:hover { box-shadow: 8px 8px 0 0 var(--ds-pink); }
:where(:root[data-theme="riso"]) .ri-btn:active { transform: translate(6px, 6px); box-shadow: 0 0 0 0 var(--ds-key); }
:where(:root[data-theme="riso"]) .ri-btn:focus-visible { outline: 3px solid var(--ds-pink); outline-offset: 3px; }
:where(:root[data-theme="riso"]) .ri-btn-blue { background: var(--ds-blue); color: var(--ds-on-blue); } :where(:root[data-theme="riso"]) .ri-btn-pink { background: var(--ds-pink); color: var(--ds-on-pink); }
:where(:root[data-theme="riso"]) .ri-tag { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border: 2px solid var(--ds-key); font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; line-height: 16px; background: var(--ds-sheet); color: var(--ds-key); }
:where(:root[data-theme="riso"]) .ri-tag-blue { background: var(--ds-blue); color: var(--ds-on-blue); } :where(:root[data-theme="riso"]) .ri-tag-pink { background: var(--ds-pink); color: var(--ds-on-pink); } :where(:root[data-theme="riso"]) .ri-tag-yellow { background: var(--ds-yellow); color: var(--ds-on-yellow); } :where(:root[data-theme="riso"]) .ri-tag-positive { background: var(--ds-positive-soft); color: var(--ds-positive); }
:where(:root[data-theme="riso"]) .ri-door { display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center; min-width: 180px; }
:where(:root[data-theme="riso"]) .ri-door-n { display: inline-block; padding: 6px 12px 2px; min-width: 2.1em; text-align: center; position: relative; }
:where(:root[data-theme="riso"]) .ri-door-blue .ri-door-n { background: var(--ds-blue); color: var(--ds-on-blue); } :where(:root[data-theme="riso"]) .ri-door-pink .ri-door-n { background: var(--ds-pink); color: var(--ds-on-pink); } :where(:root[data-theme="riso"]) .ri-door-yellow .ri-door-n { background: var(--ds-yellow); color: var(--ds-on-yellow); }
:where(:root[data-theme="riso"]) .ri-door div { display: grid; gap: 2px; } :where(:root[data-theme="riso"]) .ri-door-s { font-size: 14px; color: var(--ds-key-2); }
:where(:root[data-theme="riso"]) .ri-callout { position: relative; padding: 16px 18px 16px; border: 1.5px dashed var(--ds-key); background: var(--ds-sheet); line-height: 1.5; font-size: 16px; margin-top: 8px; } :where(:root[data-theme="riso"]) .ri-callout strong { font-weight: 900; }
:where(:root[data-theme="riso"]) .ri-callout-blue { background: var(--ds-blue-soft); } :where(:root[data-theme="riso"]) .ri-callout-positive { background: var(--ds-positive-soft); } :where(:root[data-theme="riso"]) .ri-callout-negative { background: var(--ds-negative-soft); }
:where(:root[data-theme="riso"]) .ri-folio { position: absolute; top: -12px; right: 16px; background: var(--ds-key); color: var(--ds-sheet); font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; padding: 3px 9px; line-height: 16px; }
:where(:root[data-theme="riso"]) .ri-folio-br { top: auto; bottom: 10px; right: 14px; }
:where(:root[data-theme="riso"]) .ri-hl { font-weight: 700; background: linear-gradient(transparent 58%, var(--ds-yellow) 58% 92%, transparent 92%); } :root:where([data-theme="riso"].dark) .ri-hl { background: var(--ds-yellow); color: var(--ds-on-yellow); padding: 0 .12em; }
:where(:root[data-theme="riso"]) .ri-card { position: relative; background: var(--ds-sheet); border: 2px solid var(--ds-key); padding: 26px 26px 22px; max-width: 460px; box-shadow: var(--ds-shadow-hard-lg); transform: rotate(-.6deg); display: grid; gap: 12px; justify-items: start; transition: transform 160ms ease-out; }
:where(:root[data-theme="riso"]) .ri-card:hover { transform: rotate(0deg) translateY(-4px); } :where(:root[data-theme="riso"]) .ri-card-b { transform: rotate(.7deg); }
:where(:root[data-theme="riso"]) .ri-card h3 { margin: 0; } :where(:root[data-theme="riso"]) .ri-card p { margin: 0; } :where(:root[data-theme="riso"]) .ri-card-body { line-height: 1.5; }
:where(:root[data-theme="riso"]) .ri-runhead { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; padding: 14px 20px; border-bottom: 2px solid var(--ds-key); }
:where(:root[data-theme="riso"]) .ri-cover { display: grid; gap: 24px; padding: 32px 20px 40px; background-image: var(--ds-grain); }
:where(:root[data-theme="riso"]) .ri-cover-words { min-width: 0; }
:where(:root[data-theme="riso"]) .ri-kicker { display: inline-flex; align-items: center; gap: 10px; margin: 0 0 18px; }
:where(:root[data-theme="riso"]) .ri-pip { display: inline-block; width: 12px; height: 12px; border-radius: 50%; } :where(:root[data-theme="riso"]) .ri-pip-blue { background: var(--ds-blue); }
:where(:root[data-theme="riso"]) .ri-h1 { margin: 0; } :where(:root[data-theme="riso"]) .ri-h1-l1 { display: block; margin-bottom: .1em; }
:where(:root[data-theme="riso"]) .ri-h1-l2 { display: block; font-family: var(--font-display); font-weight: 900; font-size: clamp(64px, 11vw, 150px); line-height: .84; letter-spacing: -.045em; color: var(--ds-blue); font-variation-settings: "SOFT" 100, "WONK" 1; padding-bottom: .08em; }
:where(:root[data-theme="riso"]) .ri-ovp { position: relative; isolation: isolate; display: inline-block; }
:where(:root[data-theme="riso"]) .ri-ovp::before, :where(:root[data-theme="riso"]) .ri-ovp::after { content: attr(data-text); position: absolute; inset: 0; pointer-events: none; mix-blend-mode: multiply; z-index: -1; }
:where(:root[data-theme="riso"]) .ri-ovp::before { color: var(--ds-pink); transform: translate(.045em, .03em); } :where(:root[data-theme="riso"]) .ri-ovp::after { color: var(--ds-yellow); transform: translate(-.035em, .05em); }
:root:where([data-theme="riso"].dark) .ri-ovp::before, :root:where([data-theme="riso"].dark) .ri-ovp::after { mix-blend-mode: screen; }
:where(:root[data-theme="riso"]) .ri-dek { margin: 24px 0 0; max-width: 30ch; }
:where(:root[data-theme="riso"]) .ri-imprint { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-top: 24px; color: var(--ds-key-2); }
:where(:root[data-theme="riso"]) .ri-turn { display: inline-block; margin-top: 28px; border-bottom: 2px solid var(--ds-key); padding-bottom: 4px; }
:where(:root[data-theme="riso"]) .ri-cover-art { position: relative; } :where(:root[data-theme="riso"]) .ri-cover-svg { display: block; width: 100%; height: auto; }
:where(:root[data-theme="riso"]) .ri-badge { position: absolute; right: 8px; top: 8px; width: 108px; height: 108px; border-radius: 50%; background: var(--ds-pink); color: var(--ds-on-pink); display: grid; place-items: center; text-align: center; transform: rotate(12deg); font-family: var(--font-mono); font-size: 10.5px; line-height: 1.3; text-transform: uppercase; letter-spacing: .06em; padding: 12px; }
:where(:root[data-theme="riso"]) .ri-badge b { display: block; font-family: var(--font-display); font-size: 26px; font-weight: 500; font-style: italic; letter-spacing: 0; text-transform: none; }
:where(:root[data-theme="riso"]) .ri-ticker { overflow: hidden; background: var(--ds-yellow); color: var(--ds-on-yellow); border-top: 2px solid var(--ds-key); border-bottom: 2px solid var(--ds-key); padding: 10px 0; }
:where(:root[data-theme="riso"]) .ri-ticker-track { display: flex; width: max-content; font-family: var(--font-mono); font-size: 13px; letter-spacing: .09em; text-transform: uppercase; }
:where(:root[data-theme="riso"]) .ri-ticker-track span { padding: 0 18px; white-space: nowrap; } :where(:root[data-theme="riso"]) .ri-ticker-track i { font-style: normal; color: var(--ds-pink); mix-blend-mode: multiply; margin: 0 10px; }
:where(:root[data-theme="riso"]) .ri-scene { display: grid; gap: 32px; padding: 40px 20px 56px; }
:where(:root[data-theme="riso"]) .ri-steps { display: grid; gap: 36px; align-content: start; justify-items: start; }
:where(:root[data-theme="riso"]) .ri-tagwrap { position: relative; transform: rotate(-2deg); margin-left: 24px; }
:where(:root[data-theme="riso"]) .ri-tag-card { position: relative; background: var(--ds-manila); color: var(--ds-on-yellow); clip-path: polygon(34px 0, 100% 0, 100% 100%, 34px 100%, 0 calc(100% - 34px), 0 34px); padding: 24px 24px 36px 62px; max-width: 420px; }
