  --ds-slide-bg: var(--ds-paper); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-band); --ds-slide-title-fg: var(--ds-ink); --ds-slide-split-a: var(--ds-ink); --ds-slide-split-a-fg: var(--ds-paper); --ds-slide-split-b: var(--ds-accent); --ds-slide-split-b-fg: var(--ds-on-accent); --ds-hero-bg: var(--ds-band); }
