:where(:root[data-theme="almanac"]) .al-serif-i { font-family: var(--font-display); font-style: italic; font-size: 20px; letter-spacing: -.02em; fill: var(--ds-hand-ink, var(--ds-ink)); } :where(:root[data-theme="almanac"]) .al-serif-t { font-family: var(--font-display); font-size: 26px; letter-spacing: -.03em; fill: var(--ds-ink); }
