:where(:root[data-theme="almanac"]) .al-tag-ink { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-paper); } :where(:root[data-theme="almanac"]) .al-tag-accent { background: var(--ds-accent); border-color: var(--ds-accent); color: var(--ds-on-accent); } :where(:root[data-theme="almanac"]) .al-tag-positive { background: var(--ds-positive-soft); border-color: var(--ds-positive-soft); color: var(--ds-positive); }
