:where(:root[data-theme="almanac"]) .al-callout { padding: 16px 0; border-top: 1px solid var(--ds-line); border-bottom: 1px solid var(--ds-line); line-height: 1.6; font-size: 16px; } :where(:root[data-theme="almanac"]) .al-callout strong { font-weight: 500; }
