:where(:root[data-theme="almanac"]) .al-nav { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 25px 20px; border-bottom: 1px solid var(--ds-line); }
:where(:root[data-theme="almanac"]) .al-wordmark { font-family: var(--font-body); font-size: 23px; font-weight: 600; letter-spacing: -.07em; }
:where(:root[data-theme="almanac"]) .al-hero { position: relative; display: grid; gap: 40px; padding: 56px 20px 72px; background: var(--ds-band); }
:where(:root[data-theme="almanac"]) .al-hero-h { margin: 0; max-width: 11ch; } :where(:root[data-theme="almanac"]) .al-hero-h em { color: var(--ds-accent); }
:where(:root[data-theme="almanac"]) .al-hero-p { margin: 28px 0 0; max-width: 400px; font-size: 17px; }
:where(:root[data-theme="almanac"]) .al-scroll { margin-top: 36px; border: 0; border-bottom: 1px solid currentColor; padding: 0 0 12px; gap: 40px; } :where(:root[data-theme="almanac"]) .al-scroll:hover { background: transparent; color: inherit; transform: none; }
:where(:root[data-theme="almanac"]) .al-arch { position: relative; justify-self: center; width: min(100%, 360px); padding: 56px 28px 36px; background: var(--ds-screen); border-radius: 180px 180px 0 0; box-shadow: var(--ds-shadow-soft); display: grid; place-items: center; text-align: center; transform: rotate(-3deg); transition: transform 500ms; }
