:where(:root[data-theme="almanac"]) .al-outcomes { display: grid; gap: 40px; padding: 56px 20px 0; }
:where(:root[data-theme="almanac"]) .al-breakdown { padding: 56px 20px 72px; }
:where(:root[data-theme="almanac"]) .al-total-bar { display: flex; height: 96px; border-radius: 70px 70px 0 0; overflow: hidden; }
:where(:root[data-theme="almanac"]) .al-total-bar span { display: flex; align-items: center; padding: 20px; font-size: 48px; letter-spacing: -.06em; }
