redline.css:
:where(:root[data-theme="redline"]) .t-display-xl { font-family: "Barlow Condensed", Impact, "Arial Narrow", sans-serif; font-size: clamp(80px, 18vw, 240px); line-height: .82; font-weight: 700; letter-spacing: -0.025em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .t-display-l { font-family: "Barlow Condensed", Impact, "Arial Narrow", sans-serif; font-size: clamp(48px, 7.5vw, 104px); line-height: .9; font-weight: 700; letter-spacing: -0.025em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .t-display-m { font-family: "Barlow Condensed", Impact, "Arial Narrow", sans-serif; font-size: 44px; line-height: 40px; font-weight: 700; letter-spacing: -0.02em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .t-title { font-family: "Barlow Condensed", Impact, "Arial Narrow", sans-serif; font-size: 24px; line-height: 26px; font-weight: 700; letter-spacing: -0.01em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .t-body-l { font-family: "DM Sans", system-ui, sans-serif; font-size: 19px; line-height: 1.5; font-weight: 400; }
:where(:root[data-theme="redline"]) .t-body { font-family: "DM Sans", system-ui, sans-serif; font-size: 16px; line-height: 1.55; font-weight: 400; }
:where(:root[data-theme="redline"]) .t-body-s { font-family: "DM Sans", system-ui, sans-serif; font-size: 13px; line-height: 18px; font-weight: 400; }
:where(:root[data-theme="redline"]) .t-label { font-family: "DM Mono", ui-monospace, Menlo, monospace; font-size: 11px; line-height: 16px; font-weight: 400; letter-spacing: 0.09em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .t-numeral { font-family: "Barlow Condensed", Impact, "Arial Narrow", sans-serif; font-size: 64px; line-height: 56px; font-weight: 700; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="redline"]) .t-mono { font-family: "DM Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="redline"]) { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-red); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-paper-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 1px solid var(--ds-line); --ds-tpl-radius: 0; --ds-tpl-rule: 2px solid var(--ds-ink); --ds-tag-radius: 0; --ds-slide-bg: var(--ds-paper-raised); --ds-slide-title-bg: var(--ds-red); --ds-slide-title-fg: var(--ds-on-red); --ds-slide-split-a: var(--ds-ink); --ds-slide-split-a-fg: var(--ds-on-ink); --ds-slide-split-b: var(--ds-red); --ds-slide-split-b-fg: var(--ds-on-red); --ds-hero-bg: var(--ds-red); --ds-hero-fg: var(--ds-on-red); --ds-hero-muted: var(--ds-on-red); }
:where(:root[data-theme="redline"]) .ds-tpl-brand { font-style: italic; text-transform: lowercase; letter-spacing: -.06em; font-size: 24px; }
:where(:root[data-theme="redline"]) .ds-tpl-tag { font-family: var(--font-mono); font-weight: 400; border: 1px solid currentColor; }
:where(:root[data-theme="redline"]) .ds-tpl-tag.is-idle { background: transparent; }
:where(:root[data-theme="redline"]) .ds-tpl-slide-h { font-size: 13cqw; line-height: .85; }
:where(:root[data-theme="redline"]) .ds-tpl-slide-big { font-size: 28cqw; }
:where(:root[data-theme="redline"]) .ds-tpl-hero .ds-tpl-kicker { color: var(--ds-on-red); }
:where(:root[data-theme="redline"]) .ds-tpl-hero .rl-btn { border-color: var(--ds-on-red); color: var(--ds-on-red); } :where(:root[data-theme="redline"]) .ds-tpl-hero .rl-btn-primary { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-on-ink); } :where(:root[data-theme="redline"]) .ds-tpl-hero .rl-btn-primary:hover { background: var(--ds-paper); border-color: var(--ds-paper); color: var(--ds-ink); }
:where(:root[data-theme="redline"]) .ds-tpl-hero .h-ground { fill: var(--ds-paper); } :where(:root[data-theme="redline"]) .ds-tpl-hero .h-fill { fill: var(--ds-ink); } :where(:root[data-theme="redline"]) .ds-tpl-hero .h-fill2 { fill: var(--ds-paper-sunk); }
/* svg vocabulary */
:where(:root[data-theme="redline"]) .rl-paper { fill: var(--ds-paper); } :where(:root[data-theme="redline"]) .rl-red { fill: var(--ds-hand-fill); } :where(:root[data-theme="redline"]) .rl-ink { fill: var(--ds-hand-ink); }
:where(:root[data-theme="redline"]) .rl-dot { fill: var(--ds-hand-muted); } :where(:root[data-theme="redline"]) .rl-dot-on, :where(:root[data-theme="redline"]) .rl-dot-red { fill: var(--ds-hand-fill); } :where(:root[data-theme="redline"]) .rl-dot-paper { fill: var(--ds-paper); opacity: .35; }
:where(:root[data-theme="redline"]) .rl-stamp-rim { fill: none; stroke: currentColor; stroke-width: 2; stroke: var(--ds-hand-ink); }
:where(:root[data-theme="redline"]) .rl-svg-mono { font-family: var(--font-mono); font-size: 10px; letter-spacing: .09em; fill: var(--ds-hand-ink); } :where(:root[data-theme="redline"]) .rl-svg-soft { fill: var(--ds-ink-soft); }
:where(:root[data-theme="redline"]) .rl-on-red { fill: var(--ds-on-red); } :where(:root[data-theme="redline"]) .rl-on-ink { fill: var(--ds-on-ink); }
:where(:root[data-theme="redline"]) .rl-svg-huge { font-family: var(--font-display); font-weight: 700; font-size: 150px; letter-spacing: -.025em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="redline"]) .rl-svg-big { font-family: var(--font-display); font-weight: 700; font-size: 72px; letter-spacing: -.025em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="redline"]) .rl-svg-bar { font-family: var(--font-display); font-weight: 700; font-size: 40px; letter-spacing: -.03em; }
:where(:root[data-theme="redline"]) .rl-svg-stamp { font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="redline"]) .rl-svg-mark { font-family: var(--font-display); font-weight: 700; font-size: 220px; letter-spacing: -.03em; fill: var(--ds-hand-fill); opacity: .2; }
/* authored components */
:where(:root[data-theme="redline"]) .rl-btn { font-family: var(--font-display); font-size: 18px; font-weight: 700; text-transform: uppercase; letter-spacing: -.005em; line-height: 20px; padding: 10px 18px; border: 2px solid var(--ds-ink); border-radius: 0; background: transparent; color: var(--ds-ink); cursor: pointer; transition: background 200ms, color 200ms; }
:where(:root[data-theme="redline"]) .rl-btn:hover { background: var(--ds-ink); color: var(--ds-on-ink); }
:where(:root[data-theme="redline"]) .rl-btn:focus-visible { outline: 3px solid var(--ds-red); outline-offset: 5px; }
:where(:root[data-theme="redline"]) .rl-btn-primary { background: var(--ds-red); border-color: var(--ds-red); color: var(--ds-on-red); } :where(:root[data-theme="redline"]) .rl-btn-primary:hover { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-on-ink); }
:where(:root[data-theme="redline"]) .rl-btn-ink { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-on-ink); } :where(:root[data-theme="redline"]) .rl-btn-ink:hover { background: var(--ds-red); border-color: var(--ds-red); color: var(--ds-on-red); }
:where(:root[data-theme="redline"]) .rl-tag { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; line-height: 16px; padding: 3px 8px; border: 1px solid var(--ds-ink); color: var(--ds-ink); }
:where(:root[data-theme="redline"]) .rl-tag-red { background: var(--ds-red); border-color: var(--ds-red); color: var(--ds-on-red); }
:where(:root[data-theme="redline"]) .rl-tag.is-ok { background: var(--ds-positive-soft); color: var(--ds-positive); border-color: var(--ds-positive); } :where(:root[data-theme="redline"]) .rl-tag.is-warn { background: var(--ds-caution-soft); color: var(--ds-caution); border-color: var(--ds-caution); } :where(:root[data-theme="redline"]) .rl-tag.is-bad { background: var(--ds-negative-soft); color: var(--ds-negative); border-color: var(--ds-negative); }
:where(:root[data-theme="redline"]) .rl-stat { display: grid; gap: 6px; padding: 14px 0 0; border-top: 2px solid var(--ds-ink); min-width: 170px; } :where(:root[data-theme="redline"]) .rl-stat-red .t-numeral { color: var(--ds-red-ink); } :where(:root[data-theme="redline"]) .rl-stat-note { font-size: 13px; color: var(--ds-ink-soft); }
:where(:root[data-theme="redline"]) .rl-callout { padding: 14px 16px; border: 1px solid var(--ds-ink); line-height: 1.5; font-size: 15px; } :where(:root[data-theme="redline"]) .rl-callout strong { font-family: var(--font-display); font-size: 18px; text-transform: uppercase; font-weight: 700; }
:where(:root[data-theme="redline"]) .rl-callout-red { background: var(--ds-red); border-color: var(--ds-red); color: var(--ds-on-red); } :where(:root[data-theme="redline"]) .rl-callout-ok { background: var(--ds-positive-soft); } :where(:root[data-theme="redline"]) .rl-callout-bad { background: var(--ds-negative-soft); }
:where(:root[data-theme="redline"]) .rl-card { display: grid; gap: 12px; justify-items: start; padding: 24px; border: 1px solid var(--ds-line); background: var(--ds-paper-raised); max-width: 560px; } :where(:root[data-theme="redline"]) .rl-card h3 { margin: 0; } :where(:root[data-theme="redline"]) .rl-card-body { margin: 0; line-height: 1.5; color: var(--ds-ink-soft); }
:where(:root[data-theme="redline"]) .rl-bar { display: flex; width: 100%; height: 64px; margin-top: 8px; } :where(:root[data-theme="redline"]) .rl-bar > span { display: flex; align-items: center; gap: 8px; padding: 0 16px; font-family: var(--font-display); font-weight: 700; font-size: 32px; letter-spacing: -.03em; }
:where(:root[data-theme="redline"]) .rl-bar > span > span, :where(:root[data-theme="redline"]) .rl-bar > span > span > span { padding: 0; }
@container (max-width: 480px) { :where(:root[data-theme="redline"]) .rl-bar > span { min-width: 0; gap: 4px; padding: 0 8px; font-size: 20px; white-space: nowrap; } :where(:root[data-theme="redline"]) .rl-bar > span > span, :where(:root[data-theme="redline"]) .rl-bar > span > span > span { font-size: inherit; } }
:where(:root[data-theme="redline"]) .rl-bar-a { flex: 3; background: var(--ds-hand-fill2); color: var(--ds-on-ink); } :where(:root[data-theme="redline"]) .rl-bar-b { flex: 2; background: var(--ds-hand-fill); color: var(--ds-on-red); }
:where(:root[data-theme="redline"]) .rl-bar-labels { display: flex; justify-content: space-between; gap: 16px; width: 100%; font-size: 13px; color: var(--ds-ink-soft); }
:where(:root[data-theme="redline"]) .rl-stamp { display: inline-block; font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; border: 2px solid currentColor; padding: 8px 10px; transform: rotate(-4deg); }
:where(:root[data-theme="redline"]) .rl-list { border-top: 1px solid var(--ds-line); }
:where(:root[data-theme="redline"]) .rl-list-row { display: grid; grid-template-columns: 48px minmax(0, 1fr); gap: 4px 16px; padding: 16px 0; border-bottom: 1px solid var(--ds-line); align-items: baseline; } :where(:root[data-theme="redline"]) .rl-list-row h4 { margin: 0; } :where(:root[data-theme="redline"]) .rl-list-row p { margin: 0; grid-column: 2; line-height: 1.5; color: var(--ds-ink-soft); }
/* sample: three stages */
:where(:root[data-theme="redline"]) .rl-deck { display: grid; gap: 16px; }
:where(:root[data-theme="redline"]) .rl-stage { container-type: inline-size; aspect-ratio: 16 / 9; position: relative; overflow: hidden; display: flex; flex-direction: column; padding: 3.6cqw 4.2cqw; background: var(--ds-paper); color: var(--ds-ink); }
:where(:root[data-theme="redline"]) .rl-stage-red { background: var(--ds-red); color: var(--ds-on-red); } :where(:root[data-theme="redline"]) .rl-stage-ink { background: var(--ds-ink); color: var(--ds-on-ink); }
:where(:root[data-theme="redline"]) .rl-top, :where(:root[data-theme="redline"]) .rl-foot { display: flex; justify-content: space-between; gap: 2cqw; font-family: var(--font-mono); font-size: 2.2cqw; letter-spacing: .09em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .rl-top { position: relative; z-index: 2; } :where(:root[data-theme="redline"]) .rl-foot { margin-top: auto; padding-top: 2cqw; border-top: 1px solid currentColor; opacity: .75; font-size: 2cqw; text-transform: none; letter-spacing: .02em; position: relative; z-index: 2; }
:where(:root[data-theme="redline"]) .rl-brand { font-family: var(--font-display); font-weight: 700; font-style: italic; font-size: 4.2cqw; letter-spacing: -.06em; text-transform: lowercase; line-height: 1; }
:where(:root[data-theme="redline"]) .rl-cover-word { margin: 3cqw 0 0; font-family: var(--font-display); font-weight: 700; font-size: 21cqw; line-height: .82; letter-spacing: -.025em; text-transform: uppercase; }
:where(:root[data-theme="redline"]) .rl-cover-sub { margin: 3cqw 0 0; font-size: 2.8cqw; line-height: 1.4; max-width: 46%; }
:where(:root[data-theme="redline"]) .rl-stat-row { display: flex; flex-wrap: wrap; align-items: center; gap: 3cqw; margin-top: 3cqw; }
:where(:root[data-theme="redline"]) .rl-huge { font-family: var(--font-display); font-weight: 700; font-size: 26cqw; line-height: .85; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="redline"]) .rl-stat-h { margin: 0; font-family: var(--font-display); font-weight: 700; font-size: 8cqw; line-height: .9; text-transform: uppercase; letter-spacing: -.02em; }
:where(:root[data-theme="redline"]) .rl-metric-bottom { display: grid; grid-template-columns: 1fr 1fr; gap: 4cqw; margin-top: 3cqw; padding-top: 2cqw; border-top: 2px solid currentColor; }
:where(:root[data-theme="redline"]) .rl-metric-bottom strong { display: block; font-family: var(--font-display); font-weight: 700; font-size: 7cqw; line-height: .9; letter-spacing: -.02em; } :where(:root[data-theme="redline"]) .rl-metric-bottom p { margin: .6cqw 0 0; font-size: 2.6cqw; }
:where(:root[data-theme="redline"]) .rl-mark { position: absolute; right: 4cqw; top: 18cqw; font-family: var(--font-display); font-weight: 700; font-size: 40cqw; line-height: 1; text-transform: uppercase; letter-spacing: -.03em; transform: rotate(-12deg); opacity: .2; color: var(--ds-red); pointer-events: none; }
:where(:root[data-theme="redline"]) .rl-decision { position: relative; z-index: 1; margin: 3cqw 0 0; font-family: var(--font-display); font-weight: 700; font-size: 11cqw; line-height: .88; letter-spacing: -.02em; text-transform: uppercase; max-width: 72%; }
:where(:root[data-theme="redline"]) .rl-decision-copy { position: relative; z-index: 1; margin: 3cqw 0 0; font-size: 2.8cqw; line-height: 1.4; max-width: 60%; }
:where(:root[data-theme="redline"]) .rl-stage .rl-stamp { position: relative; z-index: 1; align-self: flex-start; margin-top: 3cqw; font-size: 2cqw; padding: 1.2cqw 1.6cqw; }
