nocturne.css:
:where(:root[data-theme="nocturne"]) .t-display-xl { font-family: "Newsreader", Georgia, serif; font-size: clamp(48px, 7.5vw, 104px); line-height: .92; font-weight: 300; letter-spacing: -0.03em; }
:where(:root[data-theme="nocturne"]) .t-display-l { font-family: "Newsreader", Georgia, serif; font-size: clamp(32px, 4.5vw, 56px); line-height: 1; font-weight: 300; letter-spacing: -0.02em; }
:where(:root[data-theme="nocturne"]) .t-display-italic { font-family: "Newsreader", Georgia, serif; font-size: clamp(32px, 4.5vw, 56px); line-height: 1; font-weight: 400; letter-spacing: -0.02em; font-style: italic; }
:where(:root[data-theme="nocturne"]) .t-caps { font-family: "Cinzel", "Trajan Pro", Georgia, serif; font-size: 12px; line-height: 18px; font-weight: 500; letter-spacing: 0.3em; text-transform: uppercase; }
:where(:root[data-theme="nocturne"]) .t-title { font-family: "Newsreader", Georgia, serif; font-size: 24px; line-height: 30px; font-weight: 500; }
:where(:root[data-theme="nocturne"]) .t-body-l { font-family: "Newsreader", Georgia, serif; font-size: 21px; line-height: 34px; font-weight: 300; }
:where(:root[data-theme="nocturne"]) .t-body { font-family: "Newsreader", Georgia, serif; font-size: 18px; line-height: 30px; font-weight: 400; font-variant-numeric: oldstyle-nums proportional-nums; }
:where(:root[data-theme="nocturne"]) .t-note { font-family: "Newsreader", Georgia, serif; font-size: 15px; line-height: 22px; font-weight: 400; font-style: italic; }
:where(:root[data-theme="nocturne"]) .t-label { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 11px; line-height: 16px; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; }
:where(:root[data-theme="nocturne"]) .t-numeral { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 40px; line-height: 44px; font-weight: 500; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
:root:where([data-theme="nocturne"]) { --ds-cover-bg: radial-gradient(ellipse 70% 80% at 62% 42%, var(--ds-night-raised), var(--ds-night) 100%);
  --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-lamp); --ds-hand-fill2: var(--ds-cool); --ds-hand-muted: var(--ds-night-sunk); --ds-hand-ground: var(--ds-night-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-bg: radial-gradient(ellipse 70% 80% at 50% 40%, var(--ds-night-raised), var(--ds-night) 100%);
  --ds-tpl-edge: 1px solid var(--ds-line); --ds-tpl-radius: 2px; --ds-tpl-rule: 1px solid var(--ds-line); --ds-tag-radius: 999px;
  --ds-slide-bg: var(--ds-night-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: radial-gradient(ellipse 80% 90% at 50% 30%, var(--ds-night-raised), var(--ds-night) 100%); --ds-slide-title-fg: var(--ds-ink);
  --ds-slide-split-a: var(--ds-lamp); --ds-slide-split-a-fg: var(--ds-on-lamp); --ds-slide-split-b: var(--ds-cool); --ds-slide-split-b-fg: var(--ds-night);
  --ds-hero-bg: radial-gradient(ellipse 60% 90% at 70% 50%, var(--ds-night-raised), var(--ds-night) 100%); }
:where(:root[data-theme="nocturne"]) .ds-tpl-slide-h, :where(:root[data-theme="nocturne"]) .ds-tpl-hero-h, :where(:root[data-theme="nocturne"]) .ds-tpl-ed-h { font-weight: 300; letter-spacing: -.02em; }
:where(:root[data-theme="nocturne"]) .ds-tpl-slide-big { font-family: var(--font-mono); font-weight: 500; color: var(--ds-lamp); text-shadow: var(--ds-glow-text); }
:where(:root[data-theme="nocturne"]) .ds-tpl-brand { font-family: "Cinzel", Georgia, serif; font-weight: 500; letter-spacing: .2em; font-size: 14px; text-transform: uppercase; }
:where(:root[data-theme="nocturne"]) .ds-tpl-pull-n { font-family: var(--font-mono); color: var(--ds-lamp); } :where(:root[data-theme="nocturne"]) .ds-tpl-dropcap { font-weight: 300; color: var(--ds-lamp); }
:where(:root[data-theme="nocturne"]) .ds-tpl-kicker { font-family: "Cinzel", Georgia, serif; letter-spacing: .26em; font-size: 11px; }
:where(:root[data-theme="nocturne"]) .ds-tpl-tag { font-family: var(--font-mono); letter-spacing: .12em; }
:where(:root[data-theme="nocturne"]) .h-glow .h-ink { opacity: .32; } .light :where(:root[data-theme="nocturne"]) .h-glow .h-ink { opacity: .16; }
:where(:root[data-theme="nocturne"]) .h-text { paint-order: stroke; stroke: var(--ds-night); stroke-width: 3px; stroke-linejoin: round; }
:where(:root[data-theme="nocturne"]) .h-num { font-family: var(--font-display); font-weight: 300; font-size: 46px; fill: var(--ds-lamp); letter-spacing: -.02em; }
:where(:root[data-theme="nocturne"]) .n-night { fill: var(--ds-night); } :where(:root[data-theme="nocturne"]) .n-star circle { fill: var(--ds-ink); opacity: .55; } .light :where(:root[data-theme="nocturne"]) .n-star circle { opacity: 0; }
:where(:root[data-theme="nocturne"]) .n-pool-in { stop-color: var(--ds-night-raised); } :where(:root[data-theme="nocturne"]) .n-pool-out { stop-color: var(--ds-night); }
:where(:root[data-theme="nocturne"]) .n-lit { fill: var(--ds-lamp); } :where(:root[data-theme="nocturne"]) .n-dark { fill: var(--ds-night-sunk); stroke: var(--ds-line); stroke-width: 1; }
:where(:root[data-theme="nocturne"]) .n-ribbon { fill: var(--ds-ember); } :where(:root[data-theme="nocturne"]) .n-tally line { stroke: var(--ds-ink); stroke-width: 2; stroke-linecap: round; }
:where(:root[data-theme="nocturne"]) .n-svg-label { font-family: var(--font-mono); font-size: 11px; letter-spacing: .14em; fill: var(--ds-ink-muted); } :where(:root[data-theme="nocturne"]) .n-svg-caps { font-family: "Cinzel", Georgia, serif; font-size: 11px; letter-spacing: .26em; fill: var(--ds-ink-muted); } :where(:root[data-theme="nocturne"]) .n-lamp-fill { fill: var(--ds-lamp); }
:where(:root[data-theme="nocturne"]) .n-svg-big { font-family: var(--font-display); font-weight: 300; font-size: 64px; letter-spacing: -.03em; fill: var(--ds-lamp); }
:where(:root[data-theme="nocturne"]) .n-caps { color: var(--ds-ink-muted); margin: 0 0 12px; display: flex; align-items: center; gap: 12px; } :where(:root[data-theme="nocturne"]) .n-kicker-rule { display: inline-block; width: 34px; height: 1px; background: currentColor; }
:where(:root[data-theme="nocturne"]) .n-em { font-style: italic; font-weight: 400; color: var(--ds-lamp-hot); text-shadow: var(--ds-glow-text); }
:where(:root[data-theme="nocturne"]) .n-btn { font-family: "Cinzel", Georgia, serif; font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; line-height: 18px; padding: 11px 18px; border: 1px solid var(--ds-ink); border-radius: 2px; background: transparent; color: var(--ds-ink); cursor: pointer; transition: box-shadow 300ms ease, background 200ms ease; }
:where(:root[data-theme="nocturne"]) .n-btn:hover { background: var(--ds-lamp-soft); } :where(:root[data-theme="nocturne"]) .n-btn:focus-visible { outline: 2px solid var(--ds-ember); outline-offset: 2px; }
:where(:root[data-theme="nocturne"]) .n-btn-primary { background: var(--ds-lamp); color: var(--ds-on-lamp); border-color: var(--ds-lamp); } :where(:root[data-theme="nocturne"]) .n-btn-primary:hover { background: var(--ds-lamp); box-shadow: var(--ds-halo); }
:where(:root[data-theme="nocturne"]) .n-tag { display: inline-flex; gap: 6px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--ds-line); font-family: var(--font-mono); font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--ds-ink-muted); }
:where(:root[data-theme="nocturne"]) .n-tag-lit { color: var(--ds-lamp); border-color: var(--ds-lamp); background: var(--ds-lamp-soft); } :where(:root[data-theme="nocturne"]) .n-tag-caution { color: var(--ds-caution); border-color: var(--ds-caution); } :where(:root[data-theme="nocturne"]) .n-tag-positive { color: var(--ds-positive); border-color: var(--ds-positive); }
:where(:root[data-theme="nocturne"]) .n-stat { display: grid; gap: 6px; padding: 18px 20px; border: 1px solid var(--ds-line); border-radius: 2px; background: var(--ds-night-raised); min-width: 180px; } :where(:root[data-theme="nocturne"]) .n-stat-lit { box-shadow: var(--ds-halo); border-color: var(--ds-lamp); } :where(:root[data-theme="nocturne"]) .n-stat-lit .t-numeral { color: var(--ds-lamp); }
:where(:root[data-theme="nocturne"]) .n-note { font-size: 13px; color: var(--ds-ink-muted); } :where(:root[data-theme="nocturne"]) .ds-stats { gap: 16px; }
:where(:root[data-theme="nocturne"]) .n-callout { padding: 14px 18px; border-left: 2px solid var(--ds-line); font-size: 16px; line-height: 1.55; background: var(--ds-night-raised); } :where(:root[data-theme="nocturne"]) .n-callout strong { font-weight: 500; }
:where(:root[data-theme="nocturne"]) .n-callout-caution { border-left-color: var(--ds-caution); background: var(--ds-caution-soft); } :where(:root[data-theme="nocturne"]) .n-callout-lit { border-left-color: var(--ds-lamp); background: var(--ds-lamp-soft); }
:where(:root[data-theme="nocturne"]) .n-margin { display: grid; grid-template-columns: 20px 1fr; gap: 8px; margin: 0; padding: 4px 0 0; font-style: italic; font-size: 15px; line-height: 22px; color: var(--ds-ink-soft); max-width: 36ch; } :where(:root[data-theme="nocturne"]) .n-margin-n { font-family: var(--font-mono); font-style: normal; font-size: 11px; color: var(--ds-lamp); padding-top: 3px; }
:where(:root[data-theme="nocturne"]) .n-pool { background: radial-gradient(ellipse 80% 90% at 50% 30%, var(--ds-night-raised), var(--ds-night) 100%); }
:where(:root[data-theme="nocturne"]) .n-card { padding: 24px; border: 1px solid var(--ds-line); border-radius: 2px; transition: box-shadow 300ms ease; } :where(:root[data-theme="nocturne"]) .n-card:hover { box-shadow: var(--ds-halo); }
:where(:root[data-theme="nocturne"]) .n-card h3 { margin: 4px 0 0; } :where(:root[data-theme="nocturne"]) .n-card-p { margin: 10px 0 0; line-height: 1.6; color: var(--ds-ink-soft); max-width: 56ch; }
:where(:root[data-theme="nocturne"]) .n-cells { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 16px; } :where(:root[data-theme="nocturne"]) .n-cells i { display: block; width: 28px; height: 20px; border-radius: 1px; background: var(--ds-night-sunk); border: 1px solid var(--ds-line); } :where(:root[data-theme="nocturne"]) .n-cells .n-cell-lit { background: var(--ds-lamp); border-color: var(--ds-lamp); }
:where(:root[data-theme="nocturne"]) .n-cells-lg i { width: 36px; height: 26px; } :where(:root[data-theme="nocturne"]) .n-hud { display: block; margin: 12px 0 0; color: var(--ds-ink-muted); }
:where(:root[data-theme="nocturne"]) .n-folio { display: block; margin-top: 24px; color: var(--ds-ink-muted); } :where(:root[data-theme="nocturne"]) .n-stat-row { display: grid; gap: 12px; margin-top: 28px; }
