broadsheet.css:
:where(:root[data-theme="broadsheet"]) .t-masthead { font-family: "UnifrakturCook", "Old English Text MT", serif; font-size: clamp(40px, 7vw, 84px); line-height: 1; font-weight: 700; }
:where(:root[data-theme="broadsheet"]) .t-display-xl { font-family: "Old Standard TT", "Times New Roman", serif; font-size: clamp(44px, 6.5vw, 80px); line-height: 1; font-weight: 700; letter-spacing: -0.015em; }
:where(:root[data-theme="broadsheet"]) .t-display-l { font-family: "Old Standard TT", "Times New Roman", serif; font-size: clamp(30px, 4vw, 48px); line-height: 1.08; font-weight: 700; letter-spacing: -0.01em; }
:where(:root[data-theme="broadsheet"]) .t-deck { font-family: "Old Standard TT", "Times New Roman", serif; font-size: clamp(19px, 2.2vw, 24px); line-height: 1.35; font-weight: 400; font-style: italic; }
:where(:root[data-theme="broadsheet"]) .t-body { font-family: "Old Standard TT", "Times New Roman", serif; font-size: 17px; line-height: 27px; font-weight: 400; }
:where(:root[data-theme="broadsheet"]) .t-small { font-family: "Libre Franklin", system-ui, sans-serif; font-size: 11px; line-height: 15px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
:where(:root[data-theme="broadsheet"]) .t-numeral { font-family: "Old Standard TT", "Times New Roman", serif; font-size: clamp(44px, 6vw, 72px); line-height: .95; font-weight: 700; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="broadsheet"]) .t-wire { font-family: "Courier Prime", "Courier New", monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="broadsheet"]) { --ds-cover-bg: var(--ds-newsprint); }
:where(:root[data-theme="broadsheet"]) .bs-paper { fill: var(--ds-newsprint); } :where(:root[data-theme="broadsheet"]) .bs-plate { fill: var(--ds-newsprint-raised); stroke: var(--ds-ink); stroke-width: 1; }
:where(:root[data-theme="broadsheet"]) .bs-masthead { font-family: "UnifrakturCook", serif; font-weight: 700; font-size: 34px; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-head { font-family: var(--font-display); font-weight: 700; font-size: 30px; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-deck { font-family: var(--font-display); font-style: italic; font-size: 12px; fill: var(--ds-ink-muted); }
:where(:root[data-theme="broadsheet"]) .bs-rule { stroke: var(--ds-ink); stroke-width: 2; } :where(:root[data-theme="broadsheet"]) .bs-rule-thin { stroke: var(--ds-ink); stroke-width: .8; } :where(:root[data-theme="broadsheet"]) .bs-col line { stroke: var(--ds-line); stroke-width: 2.5; }
:where(:root[data-theme="broadsheet"]) .bs-small { font-family: "Libre Franklin", sans-serif; font-weight: 600; font-size: 8px; letter-spacing: .1em; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-muted-fill { fill: var(--ds-ink-muted); } :where(:root[data-theme="broadsheet"]) .bs-red-fill { fill: var(--ds-red); }
:where(:root[data-theme="broadsheet"]) .bs-engrave path, :where(:root[data-theme="broadsheet"]) .bs-engrave circle, :where(:root[data-theme="broadsheet"]) .bs-engrave rect, :where(:root[data-theme="broadsheet"]) .bs-engrave line { fill: none; stroke: var(--ds-ink); stroke-width: 1.2; } :where(:root[data-theme="broadsheet"]) .bs-engrave-c { fill: var(--ds-newsprint-raised); stroke: var(--ds-ink); stroke-width: 1.2; } :where(:root[data-theme="broadsheet"]) .bs-tick { stroke: var(--ds-ink); stroke-width: 1.2; } :where(:root[data-theme="broadsheet"]) .bs-hand { stroke: var(--ds-ink); stroke-width: 2; stroke-linecap: round; } :where(:root[data-theme="broadsheet"]) .bs-roman { font-family: var(--font-display); font-size: 12px; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-red-wedge { fill: var(--ds-red-soft); }
:where(:root[data-theme="broadsheet"]) .bs-spec { fill: none; stroke: var(--ds-ink); stroke-width: 1.2; } :where(:root[data-theme="broadsheet"]) .bs-spec-red { fill: none; stroke: var(--ds-red); stroke-width: 1.6; } :where(:root[data-theme="broadsheet"]) .bs-pull-f { font-family: var(--font-display); font-weight: 700; font-size: 44px; }
:where(:root[data-theme="broadsheet"]) .bs-red { color: var(--ds-red); } :where(:root[data-theme="broadsheet"]) .bs-of { font-size: .5em; color: var(--ds-ink-muted); font-weight: 400; }
:where(:root[data-theme="broadsheet"]) .bs-btn { font-family: "Libre Franklin", sans-serif; font-size: 12px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; line-height: 16px; padding: 10px 16px; border: 1px solid var(--ds-ink); background: transparent; color: var(--ds-ink); cursor: pointer; }
:where(:root[data-theme="broadsheet"]) .bs-btn:hover { background: var(--ds-newsprint-sunk); } :where(:root[data-theme="broadsheet"]) .bs-btn:focus-visible { outline: 2px solid var(--ds-red); outline-offset: 2px; }
:where(:root[data-theme="broadsheet"]) .bs-btn-primary { background: var(--ds-red); color: var(--ds-on-red); border-color: var(--ds-red); } :where(:root[data-theme="broadsheet"]) .bs-btn-primary:hover { background: var(--ds-red); }
:where(:root[data-theme="broadsheet"]) .bs-tag { display: inline-flex; padding: 3px 8px; border: 1px solid var(--ds-ink); font-family: "Libre Franklin", sans-serif; font-size: 10px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; } :where(:root[data-theme="broadsheet"]) .bs-tag-red { color: var(--ds-red); border-color: var(--ds-red); } :where(:root[data-theme="broadsheet"]) .bs-tag-caution { color: var(--ds-caution); border-color: var(--ds-caution); }
:where(:root[data-theme="broadsheet"]) .bs-pull { display: grid; gap: 4px; padding: 12px 0; border-top: 2px solid var(--ds-ink); border-bottom: 1px solid var(--ds-ink); min-width: 200px; } :where(:root[data-theme="broadsheet"]) .bs-pull .t-small { color: var(--ds-ink-muted); max-width: 22ch; } :where(:root[data-theme="broadsheet"]) .ds-stats { gap: 24px; }
:where(:root[data-theme="broadsheet"]) .bs-box { padding: 12px 16px; border: 1px solid var(--ds-ink); font-size: 16px; line-height: 1.5; background: var(--ds-newsprint-raised); } :where(:root[data-theme="broadsheet"]) .bs-box strong { font-weight: 700; } :where(:root[data-theme="broadsheet"]) .bs-box-caution { border-left: 4px solid var(--ds-caution); background: var(--ds-caution-soft); } :where(:root[data-theme="broadsheet"]) .bs-box-red { border-left: 4px solid var(--ds-red); }
:where(:root[data-theme="broadsheet"]) .bs-plate-box { display: grid; gap: 8px; } :where(:root[data-theme="broadsheet"]) .bs-plate-art { border: 1px solid var(--ds-ink); background: var(--ds-newsprint-raised); padding: 12px; } :where(:root[data-theme="broadsheet"]) .bs-plate-art svg { display: block; width: 100%; height: auto; } :where(:root[data-theme="broadsheet"]) .bs-caption { color: var(--ds-ink-muted); letter-spacing: .04em; text-transform: none; font-size: 12px; line-height: 1.45; } :where(:root[data-theme="broadsheet"]) .bs-caption b { color: var(--ds-ink); letter-spacing: .1em; text-transform: uppercase; }
:where(:root[data-theme="broadsheet"]) .bs-mast { text-align: center; margin: 0; } :where(:root[data-theme="broadsheet"]) .bs-double { border-top: 2px solid var(--ds-ink); border-bottom: 1px solid var(--ds-ink); height: 3px; margin: 8px 0 0; }
:where(:root[data-theme="broadsheet"]) .bs-dateline { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 8px 0; border-bottom: 1px solid var(--ds-ink); }
:where(:root[data-theme="broadsheet"]) .bs-columns { margin-top: 24px; column-gap: 24px; column-rule: 1px solid var(--ds-line); } :where(:root[data-theme="broadsheet"]) .bs-body { margin: 0 0 14px; font-size: 16px; line-height: 1.6; text-align: justify; hyphens: auto; } :where(:root[data-theme="broadsheet"]) .bs-dropcap { float: left; font-family: var(--font-display); font-weight: 700; font-size: 58px; line-height: .8; padding: 6px 8px 0 0; }
:where(:root[data-theme="broadsheet"]) .bs-aside { display: grid; gap: 20px; align-content: start; border-left: 1px solid var(--ds-line); padding-left: 24px; }
:where(:root[data-theme="broadsheet"]) .bs-record { border-top: 2px solid var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-record-h { margin: 8px 0 4px; } :where(:root[data-theme="broadsheet"]) .bs-rec-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--ds-line); font-size: 15px; } :where(:root[data-theme="broadsheet"]) .bs-rec-v { font-family: var(--font-display); font-weight: 700; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="broadsheet"]) .bs-folio { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding-top: 8px; color: var(--ds-ink-muted); } :where(:root[data-theme="broadsheet"]) .bs-sample-bottom + .bs-double { margin-top: 32px; }
@container (min-width: 760px) { :where(:root[data-theme="broadsheet"]) .bs-sample { padding: 48px 40px 64px; } :where(:root[data-theme="broadsheet"]) .bs-sample-grid { grid-template-columns: 3fr 2fr; } :where(:root[data-theme="broadsheet"]) .bs-columns { column-count: 2; } :where(:root[data-theme="broadsheet"]) .bs-sample-bottom { grid-template-columns: 1fr 1fr; } }
:root:where([data-theme="broadsheet"]) { --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-red); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-newsprint-sunk); --ds-hand-ground: var(--ds-newsprint-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: square; --ds-hand-tex: 1; --ds-hand-bg: var(--ds-newsprint);
  --ds-tpl-edge: 1px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 1px solid var(--ds-ink); --ds-tpl-tile-shadow: none; --ds-slide-bg: var(--ds-newsprint-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-ink); --ds-slide-title-fg: var(--ds-newsprint); --ds-slide-split-a: var(--ds-red); --ds-slide-split-a-fg: var(--ds-on-red); --ds-slide-split-b: var(--ds-newsprint-sunk); --ds-slide-split-b-fg: var(--ds-ink); --ds-hero-bg: var(--ds-newsprint); --ds-tag-radius: 0; }
:where(:root[data-theme="broadsheet"]) .bs-masthead-lg { font-size: 46px; } :where(:root[data-theme="broadsheet"]) .bs-deck-sm { font-family: var(--font-display); font-size: 11px; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-dropcap-svg { font-family: var(--font-display); font-weight: 700; font-size: 34px; fill: var(--ds-ink); }
:where(:root[data-theme="broadsheet"]) .bs-wire-t { font-family: var(--font-mono); font-size: 11px; fill: var(--ds-ink); } :where(:root[data-theme="broadsheet"]) .bs-col-rule { stroke: var(--ds-line); stroke-width: 1; }
:where(:root[data-theme="broadsheet"]) .h-text { font-family: "Libre Franklin", sans-serif; font-weight: 600; font-size: 9px; letter-spacing: .1em; } :where(:root[data-theme="broadsheet"]) .h-num { font-family: var(--font-display); font-weight: 700; } :where(:root[data-theme="broadsheet"]) .h-tex-fill2 line { opacity: .7; }
:where(:root[data-theme="broadsheet"]) .ds-tpl-tag { border: 1px solid var(--ds-ink); font-family: "Libre Franklin", sans-serif; font-size: 10px; letter-spacing: .12em; background: transparent; } :where(:root[data-theme="broadsheet"]) .ds-tpl-tag.is-idle { color: var(--ds-ink-muted); border-color: var(--ds-line); }
