signout.css:
:where(:root[data-theme="signout"]) .t-display-xl { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-size: clamp(56px, 9vw, 120px); line-height: .86; font-weight: 800; letter-spacing: -0.01em; text-transform: uppercase; }
:where(:root[data-theme="signout"]) .t-display-l { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-size: clamp(36px, 5vw, 64px); line-height: .9; font-weight: 800; letter-spacing: -0.01em; text-transform: uppercase; }
:where(:root[data-theme="signout"]) .t-display-m { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-size: 28px; line-height: 28px; font-weight: 700; text-transform: uppercase; }
:where(:root[data-theme="signout"]) .t-body { font-family: "Barlow", system-ui, sans-serif; font-size: 16px; line-height: 24px; font-weight: 400; }
:where(:root[data-theme="signout"]) .t-body-s { font-family: "Barlow", system-ui, sans-serif; font-size: 13px; line-height: 18px; font-weight: 400; }
:where(:root[data-theme="signout"]) .t-label { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-size: 12px; line-height: 14px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
:where(:root[data-theme="signout"]) .t-numeral { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 36px; line-height: 40px; font-weight: 600; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="signout"]) .t-mono { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="signout"]) { --ds-cover-bg: var(--ds-kraft); }
:where(:root[data-theme="signout"]) .so-kraft { fill: var(--ds-kraft); } :where(:root[data-theme="signout"]) .so-haz rect, :where(:root[data-theme="signout"]) .so-haz-f { fill: var(--ds-hazard); } :where(:root[data-theme="signout"]) .so-haz-ink polygon { fill: var(--ds-ink); }
:where(:root[data-theme="signout"]) .so-cond { font-family: var(--font-display); font-weight: 800; font-size: 44px; fill: var(--ds-ink); } :where(:root[data-theme="signout"]) .so-cond-s { font-family: var(--font-display); font-weight: 700; font-size: 20px; fill: var(--ds-ink); }
:where(:root[data-theme="signout"]) .so-blk { font-family: var(--font-display); font-weight: 700; font-size: 11px; letter-spacing: .1em; fill: var(--ds-ink); } :where(:root[data-theme="signout"]) .so-muted-f { fill: var(--ds-ink-muted); } :where(:root[data-theme="signout"]) .so-on-pick { fill: var(--ds-on-vermilion); } :where(:root[data-theme="signout"]) .so-on-hatch { fill: var(--ds-ink); }
:where(:root[data-theme="signout"]) .so-rule2 { stroke: var(--ds-ink); stroke-width: 2; } :where(:root[data-theme="signout"]) .so-grid rect { fill: var(--ds-kraft-raised); stroke: var(--ds-ink); stroke-width: 1.5; } :where(:root[data-theme="signout"]) .so-cell-f { fill: var(--ds-kraft-raised); } :where(:root[data-theme="signout"]) .so-frame { fill: none; stroke: var(--ds-ink); stroke-width: 2; }
:where(:root[data-theme="signout"]) .so-hatch line { stroke: var(--ds-ink); stroke-width: 1.5; opacity: .55; } :where(:root[data-theme="signout"]) .so-pick { fill: var(--ds-vermilion); }
:where(:root[data-theme="signout"]) .so-stamp { fill: none; stroke: var(--ds-ink); stroke-width: 2.5; } :where(:root[data-theme="signout"]) .so-stamp-t { font-family: var(--font-display); font-weight: 800; font-size: 16px; letter-spacing: .1em; fill: var(--ds-ink); }
:where(:root[data-theme="signout"]) .so-muted { color: var(--ds-ink-muted); } :where(:root[data-theme="signout"]) .so-vermilion { color: var(--ds-vermilion); }
:where(:root[data-theme="signout"]) .so-btn { font-family: var(--font-display); font-size: 16px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; line-height: 18px; padding: 10px 16px; border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); color: var(--ds-ink); cursor: pointer; transition: background 100ms; }
:where(:root[data-theme="signout"]) .so-btn:hover { background: var(--ds-kraft-sunk); } :where(:root[data-theme="signout"]) .so-btn:focus-visible { outline: 2px solid var(--ds-vermilion); outline-offset: 2px; }
:where(:root[data-theme="signout"]) .so-btn-primary { background: var(--ds-vermilion); color: var(--ds-on-vermilion); border-color: var(--ds-ink); } :where(:root[data-theme="signout"]) .so-btn-primary:hover { background: var(--ds-vermilion); }
:where(:root[data-theme="signout"]) .so-btn-haz { background: var(--ds-hazard); color: var(--ds-ink); } :where(:root[data-theme="signout"]) .so-btn-haz:hover { background: var(--ds-hazard); }
:where(:root[data-theme="signout"]) .so-tag { display: inline-flex; padding: 3px 8px; border: 1px solid var(--ds-ink); font-family: var(--font-display); font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; background: var(--ds-kraft-raised); }
:where(:root[data-theme="signout"]) .so-tag-open { color: var(--ds-open); border-color: var(--ds-open); } :where(:root[data-theme="signout"]) .so-tag-pick { background: var(--ds-vermilion); color: var(--ds-on-vermilion); } :where(:root[data-theme="signout"]) .so-tag-taken { background: repeating-linear-gradient(45deg, var(--ds-kraft-raised) 0 5px, var(--ds-line) 5px 7px); color: var(--ds-ink-muted); }
:where(:root[data-theme="signout"]) .so-stamp-i { display: inline-flex; padding: 4px 10px; border: 2px solid var(--ds-ink); font-family: var(--font-display); font-size: 14px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; transform: rotate(-8deg); }
:where(:root[data-theme="signout"]) .so-stat { display: grid; gap: 4px; padding: 12px 16px; border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); min-width: 150px; } :where(:root[data-theme="signout"]) .so-stat-pick { background: var(--ds-vermilion); } :where(:root[data-theme="signout"]) .so-stat-pick .t-label, :where(:root[data-theme="signout"]) .so-stat-pick .so-small { color: var(--ds-on-vermilion); }
:where(:root[data-theme="signout"]) .so-of { font-size: 20px; color: var(--ds-ink-muted); } :where(:root[data-theme="signout"]) .so-small { font-family: var(--font-body); font-size: 12px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ds-ink-muted); line-height: 1.4; } :where(:root[data-theme="signout"]) .ds-stats { gap: 16px; }
:where(:root[data-theme="signout"]) .so-note { padding: 12px 16px; border: 2px solid var(--ds-ink); font-size: 15px; line-height: 1.5; background: var(--ds-kraft-raised); } :where(:root[data-theme="signout"]) .so-note strong { font-family: var(--font-display); font-weight: 700; text-transform: uppercase; letter-spacing: .06em; }
:where(:root[data-theme="signout"]) .so-note-haz { border-top: 10px solid var(--ds-hazard); background: var(--ds-hazard-soft); } :where(:root[data-theme="signout"]) .so-note-open { background: var(--ds-open-soft); } :where(:root[data-theme="signout"]) .so-note-neg { background: var(--ds-negative-soft); }
:where(:root[data-theme="signout"]) .so-sheet { border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); } :where(:root[data-theme="signout"]) .so-sheet-haz { height: 10px; background: repeating-linear-gradient(-45deg, var(--ds-hazard) 0 12px, var(--ds-ink) 12px 24px); }
:where(:root[data-theme="signout"]) .so-sheet-body { padding: 20px 24px 16px; } :where(:root[data-theme="signout"]) .so-sheet h3 { margin: 6px 0 16px; } :where(:root[data-theme="signout"]) .so-sheet-foot { margin: 14px 0 0; }
:where(:root[data-theme="signout"]) .so-grid { display: grid; grid-template-columns: minmax(140px, 1.4fr) repeat(3, minmax(0, 1fr)); border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); margin-top: 24px; }
:where(:root[data-theme="signout"]) .so-cell { padding: 8px 8px; border-right: 1px solid var(--ds-line); border-bottom: 1px solid var(--ds-line); font-family: var(--font-display); font-weight: 700; font-size: 12px; letter-spacing: .04em; text-transform: uppercase; display: grid; gap: 2px; align-content: start; min-height: 58px; min-width: 0; overflow-wrap: normal; }
:where(:root[data-theme="signout"]) .so-row-h .t-display-m { font-size: 17px; line-height: 19px; }
@container (min-width: 760px) { :where(:root[data-theme="signout"]) .so-row-h .t-display-m { font-size: 28px; line-height: 28px; } }
@container (min-width: 760px) { :where(:root[data-theme="signout"]) .so-cell { padding: 10px 12px; font-size: 14px; letter-spacing: .06em; } }
:where(:root[data-theme="signout"]) .so-grid { grid-template-columns: minmax(96px, 1.4fr) repeat(3, minmax(0, 1fr)); }
:where(:root[data-theme="signout"]) .so-cell:nth-child(4n) { border-right: 0; } :where(:root[data-theme="signout"]) .so-head { background: var(--ds-kraft-sunk); font-size: 11px; letter-spacing: .1em; color: var(--ds-ink-muted); min-height: 0; }
:where(:root[data-theme="signout"]) .so-row-h { background: var(--ds-kraft-raised); } :where(:root[data-theme="signout"]) .so-row-h .t-display-m { text-transform: uppercase; }
