sorbet.css:
:where(:root[data-theme="sorbet"]) .t-display-xl { font-family: "Fredoka", "Arial Rounded MT Bold", system-ui, sans-serif; font-size: clamp(48px, 8vw, 104px); line-height: .95; font-weight: 700; letter-spacing: -0.02em; }
:where(:root[data-theme="sorbet"]) .t-display-l { font-family: "Fredoka", "Arial Rounded MT Bold", system-ui, sans-serif; font-size: clamp(32px, 4.5vw, 56px); line-height: 1.02; font-weight: 700; letter-spacing: -0.01em; }
:where(:root[data-theme="sorbet"]) .t-title { font-family: "Fredoka", "Arial Rounded MT Bold", system-ui, sans-serif; font-size: 24px; line-height: 28px; font-weight: 600; }
:where(:root[data-theme="sorbet"]) .t-body { font-family: "Nunito", system-ui, sans-serif; font-size: 17px; line-height: 27px; font-weight: 400; }
:where(:root[data-theme="sorbet"]) .t-body-s { font-family: "Nunito", system-ui, sans-serif; font-size: 14px; line-height: 20px; font-weight: 400; }
:where(:root[data-theme="sorbet"]) .t-label { font-family: "Fredoka", "Arial Rounded MT Bold", system-ui, sans-serif; font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }
:where(:root[data-theme="sorbet"]) .t-numeral { font-family: "Fredoka", "Arial Rounded MT Bold", system-ui, sans-serif; font-size: 52px; line-height: 52px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
:where(:root[data-theme="sorbet"]) .t-mono { font-family: "DM Mono", ui-monospace, Menlo, monospace; font-size: 13px; line-height: 20px; font-weight: 400; }
:root:where([data-theme="sorbet"]) { --ds-cover-bg: var(--ds-cream); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-strawberry); --ds-hand-fill2: var(--ds-blueberry); --ds-hand-muted: var(--ds-lilac); --ds-hand-ground: var(--ds-cream-raised); --ds-hand-stroke: 3; --ds-hand-cap: round; --ds-hand-shadow: var(--ds-ink); --ds-hand-bg: var(--ds-cream-sunk);
  --ds-tpl-edge: 3px solid var(--ds-ink); --ds-tpl-radius: 20px; --ds-tpl-rule: 3px solid var(--ds-ink); --ds-tpl-tile-shadow: var(--ds-drop); --ds-tpl-shadow: none; --ds-slide-bg: var(--ds-cream-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-strawberry); --ds-slide-title-fg: var(--ds-on-strawberry); --ds-slide-split-a: var(--ds-strawberry); --ds-slide-split-a-fg: var(--ds-on-strawberry); --ds-slide-split-b: var(--ds-blueberry); --ds-slide-split-b-fg: var(--ds-on-blueberry); --ds-hero-bg: var(--ds-cream-sunk); --ds-tag-radius: 999px; }
:where(:root[data-theme="sorbet"]) .h-num { font-family: var(--font-display); font-weight: 700; } :where(:root[data-theme="sorbet"]) .h-plate, :where(:root[data-theme="sorbet"]) .h-text { font-family: var(--font-mono); }
:where(:root[data-theme="sorbet"]) .sb-cream { fill: var(--ds-cream); }
:where(:root[data-theme="sorbet"]) .sb-f-straw { fill: var(--ds-strawberry); background: var(--ds-strawberry); } :where(:root[data-theme="sorbet"]) .sb-f-mango { fill: var(--ds-mango); background: var(--ds-mango); } :where(:root[data-theme="sorbet"]) .sb-f-lime { fill: var(--ds-lime); background: var(--ds-lime); } :where(:root[data-theme="sorbet"]) .sb-f-blue { fill: var(--ds-blueberry); background: var(--ds-blueberry); } :where(:root[data-theme="sorbet"]) .sb-f-grape { fill: var(--ds-grape); background: var(--ds-grape); }
:where(:root[data-theme="sorbet"]) .sb-shadow { fill: var(--ds-hand-ink); stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linejoin: round; } :where(:root[data-theme="sorbet"]) .sb-rim { fill: var(--ds-rim); stroke: var(--ds-rim); stroke-width: 9; stroke-linejoin: round; } :where(:root[data-theme="sorbet"]) .sb-outline { stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linejoin: round; }
:where(:root[data-theme="sorbet"]) .sb-wave { fill: none; stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linecap: round; }
:where(:root[data-theme="sorbet"]) .sb-sticker-t { font-family: var(--font-display); font-weight: 700; font-size: 16px; letter-spacing: .06em; fill: var(--ds-hand-ink); } :where(:root[data-theme="sorbet"]) .sb-on-blue { fill: var(--ds-on-blueberry); color: var(--ds-on-blueberry); }
:where(:root[data-theme="sorbet"]) .sb-cover-word { font-family: var(--font-display); font-weight: 700; font-size: 72px; fill: var(--ds-hand-ink); } :where(:root[data-theme="sorbet"]) .sb-blob-t { font-family: var(--font-display); font-weight: 600; font-size: 22px; fill: var(--ds-hand-ink); } :where(:root[data-theme="sorbet"]) .sb-blob-n { font-family: var(--font-display); font-weight: 700; font-size: 64px; letter-spacing: -.02em; fill: var(--ds-hand-ink); }
:where(:root[data-theme="sorbet"]) .sb-muted { color: var(--ds-ink-muted); } :where(:root[data-theme="sorbet"]) .sb-word { color: var(--ds-strawberry); }
:where(:root[data-theme="sorbet"]) .sb-sticker { border: 3px solid var(--ds-ink); border-radius: 20px; background: var(--ds-cream-raised); box-shadow: var(--ds-sticker); }
:where(:root[data-theme="sorbet"]) .sb-btn { font-family: var(--font-display); font-size: 16px; font-weight: 600; line-height: 20px; padding: 11px 22px; border: 3px solid var(--ds-ink); border-radius: 999px; background: var(--ds-cream-raised); color: var(--ds-ink); box-shadow: var(--ds-drop); cursor: pointer; transition: transform 160ms var(--ds-spring), box-shadow 160ms var(--ds-spring); }
:where(:root[data-theme="sorbet"]) .sb-btn:hover { transform: scale(1.03); } :where(:root[data-theme="sorbet"]) .sb-btn:active { transform: translateY(4px); box-shadow: 2px 2px 0 0 var(--ds-ink); } :where(:root[data-theme="sorbet"]) .sb-btn:focus-visible { outline: 3px solid var(--ds-blueberry); outline-offset: 3px; }
:where(:root[data-theme="sorbet"]) .sb-btn-primary { background: var(--ds-strawberry); color: var(--ds-on-strawberry); } :where(:root[data-theme="sorbet"]) .sb-btn-mango { background: var(--ds-mango); } :where(:root[data-theme="sorbet"]) .sb-btn-sm { padding: 7px 16px; font-size: 14px; }
:where(:root[data-theme="sorbet"]) .sb-tag { display: inline-flex; align-items: center; padding: 3px 12px; border: 2px solid var(--ds-ink); border-radius: 999px; font-family: var(--font-display); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; background: var(--ds-cream-raised); color: var(--ds-ink); line-height: 16px; }
:where(:root[data-theme="sorbet"]) .sb-tag-straw { background: var(--ds-strawberry); } :where(:root[data-theme="sorbet"]) .sb-tag-blue { background: var(--ds-blueberry); color: var(--ds-on-blueberry); } :where(:root[data-theme="sorbet"]) .sb-tag-mango { background: var(--ds-mango); } :where(:root[data-theme="sorbet"]) .sb-tag-lime { background: var(--ds-lime); }
:where(:root[data-theme="sorbet"]) .sb-sticker-chip { display: inline-flex; padding: 5px 14px; border: 3px solid var(--ds-ink); border-radius: 999px; background: var(--ds-mango); color: var(--ds-ink); font-family: var(--font-display); font-weight: 700; font-size: 14px; letter-spacing: .04em; box-shadow: var(--ds-sticker); transform: rotate(-6deg); }
:where(:root[data-theme="sorbet"]) .ds-tpl-tag { border: 2px solid var(--ds-ink); font-family: var(--font-display); } :where(:root[data-theme="sorbet"]) .ds-tpl-tag.is-ok { background: var(--ds-lime); color: var(--ds-ink); } :where(:root[data-theme="sorbet"]) .ds-tpl-tag.is-warn { background: var(--ds-mango); color: var(--ds-ink); } :where(:root[data-theme="sorbet"]) .ds-tpl-tag.is-bad { background: var(--ds-strawberry); color: var(--ds-ink); } :where(:root[data-theme="sorbet"]) .ds-tpl-tag.is-idle { background: var(--ds-lilac); }
:where(:root[data-theme="sorbet"]) .sb-stat { display: grid; gap: 6px; padding: 18px 22px; min-width: 190px; } :where(:root[data-theme="sorbet"]) .sb-stat-mango { background: var(--ds-mango); color: var(--ds-ink); } :where(:root[data-theme="sorbet"]) .sb-stat-mango .t-label, :where(:root[data-theme="sorbet"]) .sb-stat-mango .sb-small { color: var(--ds-ink); }
:where(:root[data-theme="sorbet"]) .sb-scoops { display: flex; margin-top: 4px; } :where(:root[data-theme="sorbet"]) .sb-scoop { display: inline-block; width: 28px; height: 28px; border-radius: 999px; border: 3px solid var(--ds-ink); margin-right: -8px; }
:where(:root[data-theme="sorbet"]) .sb-small { font-family: var(--font-body); font-size: 13px; color: var(--ds-ink-muted); line-height: 1.4; } :where(:root[data-theme="sorbet"]) .ds-stats { gap: 24px; }
:where(:root[data-theme="sorbet"]) .sb-bubble { position: relative; padding: 14px 20px; border: 3px solid var(--ds-ink); border-radius: 20px; background: var(--ds-cream-raised); box-shadow: var(--ds-sticker); font-size: 15px; line-height: 1.4; margin-bottom: 8px; } :where(:root[data-theme="sorbet"]) .sb-bubble strong { font-family: var(--font-display); font-weight: 600; }
:where(:root[data-theme="sorbet"]) .sb-bubble::after { content: ""; position: absolute; left: 28px; bottom: -14px; width: 20px; height: 20px; background: inherit; border-right: 3px solid var(--ds-ink); border-bottom: 3px solid var(--ds-ink); transform: rotate(45deg) skew(10deg, 10deg); }
:where(:root[data-theme="sorbet"]) .sb-bubble-lime { background: var(--ds-lime); } :where(:root[data-theme="sorbet"]) .sb-bubble-mango { background: var(--ds-mango); } :where(:root[data-theme="sorbet"]) .sb-bubble-straw { background: var(--ds-strawberry); } :where(:root[data-theme="sorbet"]) .ds-callouts { gap: 20px; }
:where(:root[data-theme="sorbet"]) .sb-dot { display: inline-block; width: 40px; height: 40px; border-radius: 999px; border: 3px solid var(--ds-ink); }
:where(:root[data-theme="sorbet"]) .sb-card { position: relative; padding: 24px; display: grid; gap: 6px; } :where(:root[data-theme="sorbet"]) .sb-card-chip { position: absolute; top: -14px; right: 18px; } :where(:root[data-theme="sorbet"]) .sb-card h3 { margin: 0; } :where(:root[data-theme="sorbet"]) .sb-card-p { margin: 4px 0 8px; line-height: 1.5; color: var(--ds-ink-muted); max-width: 52ch; }
:where(:root[data-theme="sorbet"]) .sb-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; } :where(:root[data-theme="sorbet"]) .sb-row-start { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 24px; }
:where(:root[data-theme="sorbet"]) .sb-hero { display: grid; gap: 32px; margin-top: 28px; align-items: center; } :where(:root[data-theme="sorbet"]) .sb-hero-chip { margin-bottom: 20px; } :where(:root[data-theme="sorbet"]) .sb-sample-h { margin: 0; max-width: 11ch; } :where(:root[data-theme="sorbet"]) .sb-sample-lede { margin-top: 16px; max-width: 42ch; }
:where(:root[data-theme="sorbet"]) .sb-hero-art svg { display: block; width: min(100%, 360px); height: auto; margin: 0 auto; }
